	function UI.maxThemeName(): string
		local t = cfg.maxTheme
		return if type(t) == "string" and (THEMES[t] ~= nil or t == "Custom") then t else "Max"
	end
	if UI.MAX_THEMES[cfg.theme] then
		cfg.theme = "Obsidian"
	end
