			UI.mouseBound = true
			pcall(RunService.UnbindFromRenderStep, RunService, "cocaine_menuMouse")
			pcall(RunService.BindToRenderStep, RunService, "cocaine_menuMouse", Enum.RenderPriority.Last.Value, function()
				pcall(UI.mouseTick)
			end)
		end

		Menu.layout()
