				})
			UI.acrylic(wash, { light = 0, grain = 0.96, radius = 12, z = 2 })

			if UI.glowRadial then
				for _, spec in ipairs({ { C.accent, 0.72, math.floor(RAIL_W * 0.55), px(80), px(240), px(190) }, { C.accent2, 0.8, px(170), MENU_H - px(90), px(260), px(260) } }) do
