		logo.Name = "Logo"
		logo.Size = UDim2.new(1, 0, 0, LOGO_H)
		logo.ZIndex = 4
		logo.Active = true
		local gemPx = px(20)
		local gemHolder = frame(logo)
		gemHolder.Size = UDim2.fromOffset(gemPx, gemPx)
		gemHolder.AnchorPoint = Vector2.new(0, 0.5)
		gemHolder.Position = UDim2.new(0, px(18), 0.5, 0)
