		Menu.curtain = nil
		Menu.pageCurtain = nil
		Menu.navSel = nil
		Menu.navLiquid = nil
		Menu.placeNav = nil
		Menu.hostBase = nil
		Menu.paintHitboxes = nil
		UI.gui = nil
		UI.root = nil
		UI.popupHost = nil
		Menu.tabBtns = {}
		Menu.pages = {}
		Menu.subs = {}
	end

	function Menu.rebuild()
		local wasOpen = S.menuOpen
		local tab = Menu.activeTab
		Menu.destroy()
		S.menuOpen = false
		Menu.build()
		if tab ~= "" and Menu.pages[tab] then
			Menu.showTab(tab)
		end
		if wasOpen then
			Menu.set(true)
		end
	end
	function Menu.applyTheme()
		UI.applyTheme()
		Menu.rebuild()
		if S.hud and S.hud.retheme then
			pcall(S.hud.retheme)
		end
		notify("Theme: " .. UI.themeName(), 2, "ok")
		log("INFO", "theme:", UI.themeName())
	end
	S.rebuildMenu = Menu.rebuild
	S.applyTheme = Menu.applyTheme
	S.ui.openBindPopup = function(cfgKey: string)
		UI.openBindPopup(cfgKey)
	end
	S.ui.closeBindPopup = UI.closeBindPopup
	S.ui.search = UI.search
	S.ui.setMode = function(mode: string)
		UI.setMode(mode)
		if Menu.refreshModeSwitch then
			Menu.refreshModeSwitch()
		end
	end

	local lastSyncAt = 0
	function Menu.syncNow(tab: string?)
		local owner = UI.syncTab or {}
		local lazy = UI.lazySync
		for i, fn in ipairs(UI.sync) do
			local t = owner[i]
			if t == nil or t == tab or not lazy[fn] then
				pcall(fn)
			end
		end
	end
	function Menu.tick(enemies: { any })
		if not S.menuOpen then
			return
		end
		if Menu.dragTo and Menu.applyDrag then
			Menu.applyDrag()
		end
		local now = os.clock()
		if now - lastSyncAt >= 0.066 then
			lastSyncAt = now
			Menu.syncNow(Menu.activeTab)
		end
	end

	local KI: any = { keyMeta = {}, tabs = {}, localSeq = 0, visStates = {}, keybinds = {}, dirty = true }
	S.kicia = KI

	local DUMMY: any
	DUMMY = setmetatable({}, {
		__index = function()
			return DUMMY
		end,
		__call = function()
			return DUMMY
		end,
	})

	local function newSignal(): any
		local K = genv().KiciaRebuild
		if K and K.Signal then
			return K.Signal.new()
		end
		local handlers = {}
		local sig = {}
		function sig:Connect(fn)
			local h = { fn = fn }
			table.insert(handlers, h)
			return {
				Connected = true,
				Disconnect = function()
					local i = table.find(handlers, h)
					if i then
						table.remove(handlers, i)
					end
				end,
			}
		end
		function sig:Fire(...)
			for _, h in ipairs(table.clone(handlers)) do
				task.spawn(h.fn, ...)
			end
		end
		sig.FireSync = sig.Fire
		function sig:Destroy()
			table.clear(handlers)
		end
		return sig
	end

	local function pathText(path: any): string
		local parts = {}
		for i, p in ipairs(path) do
			parts[i] = tostring(p)
		end
		return table.concat(parts, ".")
	end

	local function registerKey(path: any, kind: string?): (string, any)
		local key = "k:" .. pathText(path)
		local meta = KI.keyMeta[key]
		if not meta then
			meta = { key = key, path = table.clone(path) }
			KI.keyMeta[key] = meta
		end
		meta.kind = kind or meta.kind
		return key, meta
	end
	local function registerLocal(default: any, kind: string?): (string, any)
		KI.localSeq += 1
		local key = "k:local" .. KI.localSeq
		local meta = { key = key, kind = kind, value = default, isLocal = true }
		KI.keyMeta[key] = meta
		return key, meta
	end
	local function metaGet(meta: any): any
		if meta.get then
			local okG, vG = pcall(meta.get)
			if okG then
				return vG
			end
			return nil
		end
		if meta.isLocal then
			return meta.value
		end
		local a = KI.adapter
		if not a then
			return nil
		end
		local ok, v = pcall(a.Get, a, meta.path)
		if ok then
			return v
		end
		return nil
	end
	local function metaSet(meta: any, v: any)
		if meta.set then
			local okS, errS = pcall(meta.set, v)
			if not okS then
				log("WARN", "ue set failed:", tostring(errS))
			end
			return
		end
		if meta.isLocal then
			meta.value = v
			if meta.onLocal then
				meta.onLocal(v)
			end
			return
		end
		local a = KI.adapter
		if a then
			local ok, err = pcall(a.Set, a, meta.path, v)
			if not ok then
				log("WARN", "kicia store set failed:", pathText(meta.path), tostring(err))
			end
		end
	end
	local function colorToTable(v: any): { number }
		if typeof(v) == "Color3" then
			return { math.floor(v.R * 255 + 0.5), math.floor(v.G * 255 + 0.5), math.floor(v.B * 255 + 0.5) }
		end
		return { 255, 255, 255 }
	end

	local function multiSetFrom(v: any, meta: any): any
		local set = {}
		if type(v) == "table" then
			if #v > 0 then
				meta.shape = "array"
				for _, o in ipairs(v) do
					set[o] = true
				end
			else
				meta.shape = "set"
				for k, on in pairs(v) do
					if on == true then
						set[k] = true
					end
				end
			end
		end
		return set
	end
	local function multiToValue(set: any, meta: any): any
		if meta.shape == "array" then
			local out = {}
			local order = meta.options or {}
			for _, o in ipairs(order) do
				if set[o] then
					table.insert(out, o)
				end
			end
			return out
		end
		local out = {}
		for k, on in pairs(set) do
			if on then
				out[k] = true
			end
		end
		return out
	end
	setmetatable(cfg, {
		__index = function(_, k)
			if type(k) ~= "string" or string.sub(k, 1, 2) ~= "k:" then
				return nil
			end
			local meta = KI.keyMeta[k]
			if not meta then
				return nil
			end
			local v = metaGet(meta)
			if meta.kind == "color" then
				return colorToTable(v)
			elseif meta.kind == "multi" then
				local set = multiSetFrom(v, meta)
				return setmetatable({}, {
					__index = function(_, o)
						return set[o]
					end,
					__newindex = function(_, o, on)
						set[o] = if on then true else nil
						metaSet(meta, multiToValue(set, meta))
					end,
				})
			end
			return v
		end,
		__newindex = function(t, k, v)
			if type(k) == "string" and string.sub(k, 1, 2) == "k:" then
				local meta = KI.keyMeta[k]
				if meta then
					if meta.kind == "color" and type(v) == "table" then
						v = Color3.fromRGB(v[1] or 255, v[2] or 255, v[3] or 255)
					elseif meta.kind == "multi" and type(v) == "table" then
						v = multiToValue(v, meta)
					end
					metaSet(meta, v)
					return
				end
			end
			rawset(t, k, v)
		end,
	})

	local Handle: any = {}
	Handle.__index = function(h, k)
		if k == "Value" then
			local meta = rawget(h, "_meta")
			if meta then
				return metaGet(meta)
			end
			return rawget(h, "_value")
		end
		local m = Handle[k]
		if m ~= nil then
			return m
		end
		if type(k) == "string" and string.match(k, "^%u") then
			return DUMMY
		end
		return nil
	end
	local function newHandle(kind: string, opts: any): any
		local h = setmetatable({
			_kind = kind,
			_opts = opts or {},
			_cbs = {},
			visible = true,
			enabled = true,
			Row = { Label = (opts or {}).Label, Frame = nil },
			ValueChanged = newSignal(),
			Changed = newSignal(),
			Clicked = newSignal(),
			options = {},
		}, Handle)
		return h
	end
	function Handle:_notify(v: any)
		KI.dirty = true
		self.ValueChanged:Fire(v)
		self.Changed:Fire(v)
		for _, cb in ipairs(self._cbs) do
			local ok, err = pcall(cb, v)
			if not ok then
				log("WARN", "kicia OnChanged failed:", tostring(err))
			end
		end
		local oc = self._opts.OnChanged
		if type(oc) == "function" then
			local ok, err = pcall(oc, v)
			if not ok then
				log("WARN", "kicia OnChanged failed:", tostring(err))
			end
		end
	end
	function Handle:Get()
		return self.Value
	end
	function Handle:Set(v: any, silent: any)
		local meta = self._meta
		if meta then
			self._suppress = silent == true
			metaSet(meta, v)
			self._suppress = false
		else
			self._value = v
			if silent ~= true then
				self:_notify(v)
			end
		end
	end
	function Handle:OnChanged(fn: any)
		table.insert(self._cbs, fn)
		return self
	end
	function Handle:Connect(sig: any, fn: any)
		if sig == nil or sig == DUMMY then
			return DUMMY
		end
		return sig:Connect(fn)
	end
	function Handle:SetVisible(v: any)
		self.visible = v ~= false
		KI.dirty = true
	end
	function Handle:SetEnabled(v: any)
		self.enabled = v ~= false
	end
	function Handle:SetLabel(t: any)
		self.Row.Label = t
	end
	function Handle:SetTooltip(t: any)
		self._opts.Tooltip = t
	end
	function Handle:SetOptions(list: any, labels: any)
		table.clear(self.options)
		for _, o in ipairs(list or {}) do
			table.insert(self.options, o)
		end
		if self._meta then
			self._meta.options = self.options
		end
		if labels ~= nil then
			self._opts.Labels = labels
		end
		KI.dirty = true
	end
	Handle.SetItems = Handle.SetOptions
	function Handle:Destroy() end
	function Handle:_click()
		local o = self._opts
		if o.Confirm == true then
			local now = os.clock()
			if now - (self._armedAt or -10) > 3 then
				self._armedAt = now
				notify("Click again to confirm: " .. tostring(o.Label or "action"), 3, "warn")
				return
			end
			self._armedAt = nil
		end
		self.Clicked:Fire()
		if type(o.OnClick) == "function" then
			local ok, err = pcall(o.OnClick)
			if not ok then
				log("WARN", "kicia button failed:", tostring(err))
			end
		end
	end

	local function bindHandle(h: any, kindTag: string?)
		local o = h._opts
		local key, meta
		if o.Config then
			key, meta = registerKey(o.Config, kindTag)
		else
			key, meta = registerLocal(o.Default, kindTag)
			meta.onLocal = function(v)
				if not h._suppress then
					h:_notify(v)
				end
			end
		end
		h._key, h._meta = key, meta
		if meta.path and KI.adapter then
			local okS, sig = pcall(KI.adapter.Changed, KI.adapter, meta.path)
			if okS and sig then
				sig:Connect(function(v)
					if not h._suppress then
						h:_notify(v)
					end
				end)
			end
		end
		return h
	end
	local function loadOptions(h: any)
		local o = h._opts
		local list = o.Options
		if type(o.GetOptions) == "function" then
			local ok, got = pcall(o.GetOptions)
			if ok and type(got) == "table" then
				list = got
			end
		end
		h:SetOptions(list or {})
	end

	local function parseKey(v: any): any
		if typeof(v) == "EnumItem" then
			return v
		end
		if type(v) ~= "string" or v == "" or v == "None" then
			return nil
		end
		local kind, name = string.match(v, "^(%w+)%.(%w+)$")
		if kind then
			local ok, item = pcall(function()
				return (Enum :: any)[kind][name]
			end)
			if ok and item then
				return item
			end
		end
		local ok, item = pcall(function()
			return (Enum.KeyCode :: any)[v]
		end)
		return if ok then item else nil
	end
	local function keyText(k: any): string
		if typeof(k) ~= "EnumItem" then
			return "none"
		end
		local names = {
			MouseButton1 = "mb1", MouseButton2 = "mb2", MouseButton3 = "mb3", LeftShift = "lshift", RightShift = "rshift",
			LeftControl = "lctrl", RightControl = "rctrl", LeftAlt = "lalt", RightAlt = "ralt",
		}
		return names[k.Name] or string.lower(k.Name)
	end
	local function makeKeybind(opts: any): any
		local h = newHandle("keybind", opts)
		local def = opts.Default or {}
		h.Value = { Key = def.Key or "None", Mode = def.Mode or (opts.Modes and opts.Modes[1]) or "Toggle" }
		if parseKey(h.Value.Key) then
			h.Value.Key = parseKey(h.Value.Key)
		else
			h.Value.Key = "None"
		end
		h.Active = false
		h.FeatureEnabled = false
		h.ShowInList = opts.ShowInList ~= false
		h.Invisible = false
		h.ActiveChanged = newSignal()
		h.ShowInListChanged = newSignal()
		h.InvisibleChanged = newSignal()
		function h:Set(v: any, silent: any)
			local key = v.Key
			if typeof(key) ~= "EnumItem" then
				key = parseKey(key) or "None"
			end
			local mode = v.Mode or self.Value.Mode
			if key == self.Value.Key and mode == self.Value.Mode then
				return
			end
			self.Value = { Key = key, Mode = mode }
			self.ValueChanged:Fire(self.Value)
			if silent ~= true then
				self.Changed:Fire(self.Value)
				for _, cb in ipairs(self._cbs) do
					pcall(cb, self.Value)
				end
			end
			if self._applyOut then
				self._applyOut()
			end
			self:_refreshActive()
		end
		function h:SetKey(k: any, silent: any)
			self:Set({ Key = k, Mode = self.Value.Mode }, silent)
		end
		function h:SetMode(m: any, silent: any)
			self:Set({ Key = self.Value.Key, Mode = m }, silent)
		end
		function h:SetActive(a: any, silent: any)
			a = a == true
			if self.Active == a then
				return
			end
			self.Active = a
			self.ActiveChanged:Fire(a)
			if silent ~= true then
				self.Changed:Fire(self.Value)
			end
			if self._applyActive then
				self._applyActive()
			end
		end
		function h:SetFeatureEnabled(e: any)
			self.FeatureEnabled = e == true
			self:_refreshActive()
		end
		function h:SetShowInList(v: any, silent: any)
			v = v == true
			if self.ShowInList == v then
				return
			end
			self.ShowInList = v
			if silent ~= true then
				self.ShowInListChanged:Fire(v)
			end
		end
		function h:SetInvisible(v: any)
			self.Invisible = v == true
			self.InvisibleChanged:Fire(self.Invisible)
		end

		function h:_refreshActive()
			if self.Value.Mode == "Always" then
				self:SetActive(self.FeatureEnabled)
			elseif not self.FeatureEnabled and self.Active then
				self:SetActive(false)
			end
		end

		local cm = opts.ConfigMap
		local a = KI.adapter
		if cm and a then
			local guard = false
			local function link(path: any, read: any, apply: any)
				if path == nil then
					return
				end
				local ok, v = pcall(a.Get, a, path)
				if ok and v ~= nil then
					guard = true
					apply(v)
					guard = false
				end
				local okS, sig = pcall(a.Changed, a, path, true)
				if okS and sig then
					sig:Connect(function(nv)
						if guard or nv == read() then
							return
						end
						guard = true
						apply(nv)
						guard = false
					end)
				end
			end
			local function write(path: any, v: any)
				if path ~= nil and not guard then
					pcall(a.Set, a, path, v)
				end
			end
			link(cm.Key, function()
				return h.Value.Key
			end, function(v)
				local k = parseKey(v)
				h:SetKey(k or "None", true)
			end)
			link(cm.Mode, function()
				return h.Value.Mode
			end, function(v)
				if type(v) == "string" then
					h:SetMode(v, true)
				end
			end)
			link(cm.ShowInList, function()
				return h.ShowInList
			end, function(v)
				h:SetShowInList(v == true, true)
			end)
			link(cm.Invisible, function()
				return h.Invisible
			end, function(v)
				h:SetInvisible(v == true)
			end)
			link(cm.Active, function()
				return h.Active
			end, function(v)
				h:SetActive(v == true, true)
			end)
			h._applyOut = function()
				write(cm.Key, h.Value.Key)
				write(cm.Mode, h.Value.Mode)
			end
			h._applyActive = function()
				write(cm.Active, h.Active)
			end
			h.ShowInListChanged:Connect(function(v)
				write(cm.ShowInList, v)
			end)
			h.InvisibleChanged:Connect(function(v)
				write(cm.Invisible, v)
			end)
		end
		table.insert(KI.keybinds, h)
		return h
	end
	local function keybindMatches(h: any, input: InputObject): boolean
		local k = h.Value.Key
		if typeof(k) ~= "EnumItem" then
			return false
		end
		if k.EnumType == Enum.KeyCode then
			return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == k
		end
		return input.UserInputType == k
	end
	if not KI.keyConn then
		KI.keyConn = {}
		table.insert(KI.keyConn, UIS.InputBegan:Connect(function(input: InputObject)
			if UIS:GetFocusedTextBox() ~= nil or KI.capturing then
				return
			end
			for _, h in ipairs(KI.keybinds) do
				if h.FeatureEnabled and keybindMatches(h, input) then
					local mode = h.Value.Mode
					if mode == "Toggle" then
						h:SetActive(not h.Active)
					elseif mode == "Hold" or mode == "Tap" then
						h:SetActive(true)
					end
				end
			end
		end))
		table.insert(KI.keyConn, UIS.InputEnded:Connect(function(input: InputObject)
			for _, h in ipairs(KI.keybinds) do
				local mode = h.Value.Mode
				if (mode == "Hold" or mode == "Tap") and h.Active and keybindMatches(h, input) then
					h:SetActive(false)
				end
			end
		end))
	end

	local Section: any = {}
	Section.__index = function(s, k)
		local m = Section[k]
		if m ~= nil then
			return m
		end
		if type(k) == "string" and string.match(k, "^%u") then
			return function()
				return DUMMY
			end
		end
		return nil
	end
	local function newSection(title: any, side: any): any
		return setmetatable({ title = tostring(title or ""), side = side or "left", items = {}, visible = true }, Section)
	end
	local function push(sec: any, kind: string, opts: any, h: any): any
		table.insert(sec.items, { kind = kind, opts = opts or {}, handle = h })
		KI.dirty = true
		return h
	end
	function Section:AddToggle(o: any)
		return push(self, "toggle", o, bindHandle(newHandle("toggle", o)))
	end
	function Section:AddSlider(o: any)
		return push(self, "slider", o, bindHandle(newHandle("slider", o)))
	end
	function Section:AddRangeSlider(o: any)
		return push(self, "range", o, bindHandle(newHandle("range", o)))
	end
	function Section:AddDropdown(o: any)
		local h = bindHandle(newHandle("dropdown", o))
		loadOptions(h)
		return push(self, "dropdown", o, h)
	end
	function Section:AddMultiDropdown(o: any)
		local h = bindHandle(newHandle("multi", o), "multi")
		loadOptions(h)
		return push(self, "multi", o, h)
	end
	function Section:AddMultiList(o: any)
		local h = bindHandle(newHandle("multi", o), "multi")
		loadOptions(h)
		return push(self, "multi", o, h)
	end
	function Section:AddList(o: any)
		local h = bindHandle(newHandle("list", o))
		loadOptions(h)
		return push(self, "list", o, h)
	end
	function Section:AddColor(o: any)
		return push(self, "color", o, bindHandle(newHandle("color", o), "color"))
	end
	function Section:AddTextBox(o: any)
		o = o or {}
		if o.Default == nil then
			o.Default = ""
		end
		return push(self, "textbox", o, bindHandle(newHandle("textbox", o)))
	end
	function Section:AddButton(o: any)
		return push(self, "button", o, newHandle("button", o))
	end
	function Section:AddLabel(o: any)
		return push(self, "label", o, newHandle("label", o))
	end
	function Section:AddDivider(o: any)
		return push(self, "divider", o, newHandle("divider", o))
	end
	function Section:AddKeybind(o: any)
		return push(self, "keybind", o, makeKeybind(o or {}))
	end

	function Section:AddSkinChanger(o: any)
		return push(self, "unsupported", o, newHandle("skin", o))
	end
	function Section:AddIconStrip(o: any)
		return push(self, "unsupported", o, newHandle("iconstrip", o))
	end
	function Section:AddViewport(o: any)
		return push(self, "unsupported", o, newHandle("viewport", o))
	end
	function Section:AddOrderedList(o: any)
		return push(self, "unsupported", o, newHandle("orderedlist", o))
	end
	function Section:AddGear(o: any)
		return newHandle("gear", o)
	end
	function Section:AddCustom(o: any)
		return push(self, "unsupported", o, newHandle("custom", o))
	end
	function Section:RemoveCustom() end

	function Section:AddGroup(o: any)
		local g = newSection(self.title, self.side)
		g.isGroup = true
		g.source, g.option = o.Source, o.Option
		if o.Visible ~= nil then
			g.visible = o.Visible ~= false
		end
		table.insert(self.items, { kind = "group", opts = o, node = g })
		KI.dirty = true
		return g
	end
	function Section:AddMultiSection(o: any)
		local panes = {}
		for _, t in ipairs(o.Titles or { "" }) do
			local p = newSection(t, self.side)
			table.insert(panes, p)
			table.insert(self.items, { kind = "pane", node = p })
		end
		return table.unpack(panes)
	end
	function Section:SetVisible(v: any)
		self.visible = v ~= false
	end
	function Section:SetTitle(t: any)
		self.title = tostring(t)
	end
	local function groupAllows(node: any): boolean
		if not node.visible then
			return false
		end
		if node.pred then
			return node.pred() == true
		end
		local src = node.source
		if src == nil then
			return true
		end
		local v = src.Value
		local opt = node.option
		if opt ~= nil then
			if type(v) == "string" then
				return v == opt
			elseif type(v) == "table" then
				return v[opt] == true or table.find(v, opt) ~= nil
			end
			return false
		end
		return v == true
	end

	local Grid: any = {}
	Grid.__index = function(s, k)
		local m = Grid[k]
		if m ~= nil then
			return m
		end
		if type(k) == "string" and string.match(k, "^%u") then
			return function()
				return DUMMY
			end
		end
		return nil
	end
	function Grid:AddSection(o: any)
		o = o or {}
		local sec = newSection(o.Title, o.Side)
		table.insert(self.sections, sec)
		KI.dirty = true
		return sec
	end
	function Grid:AddMultiSection(o: any)
		local panes = {}
		for _, t in ipairs(o.Titles or { "" }) do
			local p = newSection(t, o.Side)
			table.insert(panes, p)
			table.insert(self.sections, p)
		end
		return table.unpack(panes)
	end

	local Tab: any = {}
	Tab.__index = function(s, k)
		local m = Tab[k]
		if m ~= nil then
			return m
		end
		if type(k) == "string" and string.match(k, "^%u") then
			return function()
				return DUMMY
			end
		end
		return nil
	end
	local function newTab(o: any, parent: any): any
		o = o or {}
		return setmetatable({ label = tostring(o.Label or "Tab"), desc = o.Description, children = {}, grids = {}, parent = parent }, Tab)
	end
	function Tab:AddTab(o: any)
		local t = newTab(o, self)

		local root = self
		while root.parent do
			root = root.parent
		end
		table.insert(root.children, t)
		KI.dirty = true
		return t
	end
	function Tab:AddPage(o: any)
		return self:AddTab(o)
	end
	function Tab:Grid(o: any)
		local gr = setmetatable({ sections = {}, columns = (o or {}).Columns or 2 }, Grid)
		table.insert(self.grids, gr)
		return gr
	end
	function Tab:AddSection(o: any)
		local gr = self.grids[1] or self:Grid({ Columns = 2 })
		return gr:AddSection(o)
	end
	function Tab:AddMultiSection(o: any)
		local gr = self.grids[1] or self:Grid({ Columns = 2 })
		return gr:AddMultiSection(o)
	end
	function Tab:OnFirstOpen(fn: any)
		if type(fn) == "function" then
			local ok, err = pcall(fn, self)
			if not ok then
				log("WARN", "kicia OnFirstOpen failed:", tostring(err))
			end
		end
	end
	function Tab:Open() end

	local function decimalsOf(step: number): number
		local d = 0
		while d < 6 and math.abs(step * 10 ^ d - math.floor(step * 10 ^ d + 0.5)) > 1e-9 do
			d += 1
		end
		return d
	end
	local function fmtNumber(n: number, step: number, suffix: string): string
		local d = decimalsOf(step)
		return (string.format("%." .. d .. "f", n)) .. suffix
	end
	local function tracked(entry: any, h: any, ctx: any)
		if not entry then
			return
		end
		local state = {
			open = true,
			when = function()
				if h and h.visible == false then
					return false
				end
				return ctx.when()
			end,
		}
		entry.parent = state
		entry.advanced = false
		table.insert(KI.visStates, state)
	end

	local function replayKeybind(g: any, it: any, ctx: any)
		local h = it.handle
		local o = it.opts
		local text = tostring(o.Label or o.ListLabel or "Keybind")
		local r = g:custom(UI.M.row, text, { advanced = false })
		local entry = g.rows[#g.rows]
		g.rowLabel(r, text, { desc = o.Tooltip }, 112)
		local b = button(r, "", UI.M.value, C.text, C.surface)
		b.Name = "KeyChip"
		b.Size = UDim2.new(0, 104, 0, 22)
		b.AnchorPoint = Vector2.new(1, 0.5)
		b.Position = UDim2.new(1, 0, 0.5, 0)
		corner(b, 5)
		stroke(b, C.edge, 0)
		local function paint()
			local mode = tostring(h.Value.Mode or "")
			b.Text = if mode == "Always" then "always" else string.lower(mode) .. " · " .. keyText(h.Value.Key)
		end
		paint()
		local modes = o.Modes or { "Toggle", "Hold" }
		b.MouseButton2Click:Connect(function()
			local idx = table.find(modes, h.Value.Mode) or 0
			h:SetMode(modes[idx % #modes + 1])
			paint()
		end)
		b.MouseButton1Click:Connect(function()
			if KI.capturing then
				return
			end
			KI.capturing = true
			b.Text = "press a key…"
			local conn
			conn = UIS.InputBegan:Connect(function(input: InputObject)
				local k: any = nil
				if input.UserInputType == Enum.UserInputType.Keyboard then
					k = input.KeyCode
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.MouseButton3 then
					k = input.UserInputType
				end
				if k == nil then
					return
				end
				conn:Disconnect()
				task.delay(0.1, function()
					KI.capturing = false
				end)
				if k == Enum.KeyCode.Escape or k == Enum.KeyCode.Backspace then
					k = "None"
				end
				h:SetKey(k)
				paint()
			end)
		end)
		table.insert(UI.sync, function()
			if not KI.capturing then
				paint()
			end
		end)
		tracked(entry, h, ctx)
	end

	local function replayUEKey(g: any, it: any, ctx: any)
		local h = it.handle
		local kp = h.kp
		local text = tostring(it.opts.Label or "Keybind")
		local r = g:custom(UI.M.row, text, { advanced = false })
		local entry = g.rows[#g.rows]
		g.rowLabel(r, text, {}, 112)
		local b = button(r, "", UI.M.value, C.text, C.surface)
		b.Name = "KeyChip"
		b.Size = UDim2.new(0, 104, 0, 22)
		b.AnchorPoint = Vector2.new(1, 0.5)
		b.Position = UDim2.new(1, 0, 0, 0)
		b.Position = UDim2.new(1, 0, 0.5, 0)
		corner(b, 5)
		stroke(b, C.edge, 0)
		local function paint()
			local mode = tostring(kp.Mode or "")
			local key = tostring(kp.Value or "None")
			b.Text = if mode == "Always" then "always" else string.lower(mode) .. " · " .. string.lower(key)
		end
		paint()
		local modes = kp.Modes or { "Always", "Toggle", "Hold" }
		b.MouseButton2Click:Connect(function()
			local idx = table.find(modes, kp.Mode) or 0
			pcall(kp.SetValue, kp, { kp.Value, modes[idx % #modes + 1] })
			paint()
		end)
		b.MouseButton1Click:Connect(function()
			if KI.capturing then
				return
			end
			KI.capturing = true
			b.Text = "press a key…"
			local conn
			conn = UIS.InputBegan:Connect(function(input: InputObject)
				local name: string? = nil
				if input.UserInputType == Enum.UserInputType.Keyboard then
					name = input.KeyCode.Name
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
					name = "MB2"
				elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
					name = "MB3"
				end
				if name == nil then
					return
				end
				conn:Disconnect()
				task.delay(0.1, function()
					KI.capturing = false
				end)
				if name == "Escape" or name == "Backspace" then
					name = "None"
				end
				pcall(kp.SetValue, kp, { name, kp.Mode })
				paint()
			end)
		end)
		table.insert(UI.sync, function()
			if not KI.capturing then
				paint()
			end
		end)
		tracked(entry, h, ctx)
	end

	local function replayItems(g: any, items: any, ctx: any)
		for _, it in ipairs(items) do
			if it.skip then
				continue
			end
			local kind, o, h = it.kind, it.opts or {}, it.handle
			local text = tostring(o.Label or "")
			local desc = o.Tooltip or o.Description
			local before = #g.rows
			local ok, err = pcall(function()
				if kind == "group" then
					local node = it.node
					local sub = {
						when = function()
							return ctx.when() and groupAllows(node)
						end,
					}
					replayItems(g, node.items, sub)
					return
				elseif kind == "pane" then
					replayItems(g, it.node.items, ctx)
					return
				elseif kind == "toggle" then
					g:toggle(text, h._key, { desc = desc, advanced = false })
				elseif kind == "slider" then
					local step = tonumber(o.Step) or 1
					local suffix = tostring(o.Suffix or "")
					g:slider(text, h._key, o.Min or 0, o.Max or 100, step, {
						desc = desc,
						advanced = false,
						fmt = function(n: number): string
							return fmtNumber(n, step, suffix)
						end,
					})
				elseif kind == "dropdown" then
					loadOptions(h)
					local labels = o.Labels
					g:cycle(text, h._key, h.options, {
						desc = desc,
						advanced = false,
						fmt = if type(labels) == "table"
							then function(v: any): string
								return tostring(labels[v] or v)
							end
							else nil,
					})
				elseif kind == "multi" then
					loadOptions(h)
					h._meta.options = h.options
					g:multiselect(text, h._key, h.options, { desc = desc, advanced = false })
				elseif kind == "color" then
					g:color(text, h._key, { desc = desc, advanced = false })
				elseif kind == "textbox" then
					g:textbox(text, h._key, { desc = desc, advanced = false, placeholder = o.Placeholder, maxLen = 100000 })
				elseif kind == "button" then
					g:button(text, function()
						h:_click()
					end, nil, { desc = desc, advanced = false })
				elseif kind == "label" then
					g:note(text, { advanced = false })
				elseif kind == "list" then
					loadOptions(h)
					local labels = o.Labels
					g:list(text, {
						advanced = false,
						search = o.Search == true,
						height = o.Height or 160,
						items = function()
							local out = {}
							for _, v in ipairs(h.options) do
								table.insert(out, { id = v, label = if type(labels) == "table" then (labels[v] or v) else v })
							end
							return out
						end,
						selected = function()
							return h.Value
						end,
						onSelect = function(id: any)
							h:Set(id)
						end,
					})
				elseif kind == "keybind" then
					replayKeybind(g, it, ctx)
					return
				elseif kind == "uekey" then
					replayUEKey(g, it, ctx)
					return
				elseif kind == "range" then
					g:note(text .. " (range slider is not available in this menu)", { advanced = false })
				elseif kind == "unsupported" then
					g:note((text ~= "" and text or "this control") .. " is not available in this menu", { advanced = false })
				else
					return
				end
				tracked(g.rows[#g.rows], h, ctx)
			end)
			if not ok then
				log("WARN", ("kicia shim: %s '%s' failed to build: %s"):format(tostring(kind), text, tostring(err)))
				for i = #g.rows, before + 1, -1 do
					pcall(function()
						g.rows[i].frame:Destroy()
					end)
					table.remove(g.rows, i)
				end
			end
		end
	end

	local TOP_SECTION = {
		Combat = "Combat", Visuals = "Visuals", World = "Visuals", Cosmetics = "Visuals", Player = "Gameplay", Automation = "Gameplay",
		Settings = "Other", UE = "UE",
	}
	local TOP_ICON = {
		Combat = "gps_fixed", Visuals = "visibility", World = "public", Cosmetics = "checkroom", Player = "person_outline",
		Automation = "bolt", Settings = "settings", UE = "widgets",
	}

	function Menu.buildPages()
		table.clear(KI.visStates)
		for _, id in ipairs(KI.order or {}) do
			local tab = KI.tabByLabel[id]
			local subs = {}
			local subNodes = {}
			if #tab.children == 0 then
				table.insert(subs, tab.label)
				table.insert(subNodes, tab)
			else
				if #tab.grids > 0 then
					table.insert(subs, tab.label)
					table.insert(subNodes, tab)
				end
				for _, ch in ipairs(tab.children) do
					table.insert(subs, ch.label)
					table.insert(subNodes, ch)
				end
			end
			local st = Menu.addTab(id, subs)
			for i, sub in ipairs(subs) do
				local node = subNodes[i]
				local cols = st[sub]
				for _, grid in ipairs(node.grids) do
					for _, sec in ipairs(grid.sections) do
						if sec.visible then
							local parent = if sec.side == "right" then cols.R else cols.L
							local g = UI.group(parent, sec.title, { simple = true })
							replayItems(g, sec.items, { when = function()
								return true
							end })
						end
					end
				end
			end
		end

		local lastSig = ""
		table.insert(UI.sync, function()
			local bits = {}
			for i, state in ipairs(KI.visStates) do
				local ok, v = pcall(state.when)
				bits[i] = if ok and v then "1" else "0"
			end
			local sig = table.concat(bits)
			if sig ~= lastSig or KI.dirty then
				KI.dirty = false
				lastSig = sig
				UI.refilter()
			end
		end)
	end

	KI.BG_ORDER = { "Default", "Darker", "Black", "Midnight", "Ocean", "Forest", "Wine", "Slate" }
	local BG_PRESETS: any = {
		Darker = { tint = Color3.fromRGB(0, 0, 0), amt = 0.35 },
		Black = { tint = Color3.fromRGB(0, 0, 0), amt = 0.7 },
		Midnight = { tint = Color3.fromRGB(8, 12, 34), amt = 0.6 },
		Ocean = { tint = Color3.fromRGB(6, 22, 34), amt = 0.6 },
		Forest = { tint = Color3.fromRGB(8, 26, 16), amt = 0.6 },
		Wine = { tint = Color3.fromRGB(34, 8, 18), amt = 0.6 },
		Slate = { tint = Color3.fromRGB(40, 44, 54), amt = 0.5 },
	}
	local rebuildPending = false
	function KI.rebuildSoon()
		if rebuildPending then
			return
		end
		rebuildPending = true
		task.delay(0.4, function()
			rebuildPending = false
			pcall(Menu.rebuild)
		end)
	end

	local Rainbow: any = { entries = {}, map = {}, t = 0, acc = 0, rescanAt = 0 }
	KI.rainbow = Rainbow
	local function near(a: Color3, b: Color3): boolean
		return math.abs(a.R - b.R) + math.abs(a.G - b.G) + math.abs(a.B - b.B) < 0.006
	end
	local function nearWhich(c: Color3, o1: Color3, o2: Color3): number?
		if near(c, o1) then
			return 1
		elseif near(c, o2) then
			return 2
		end
		return nil
	end
	local function rainbowActive(): boolean
		return cfg.theme == "Rainbow"
	end
	local function rainbowPair(t: number): (Color3, Color3)
		local mode = cfg.rainbowMode
		local sat = math.clamp(tonumber(cfg.rainbowSat) or 0.75, 0, 1)
		local val = math.clamp(tonumber(cfg.rainbowVal) or 1, 0.3, 1)
		local spread = tonumber(cfg.rainbowSpread) or 0.12
		local speed = tonumber(cfg.rainbowSpeed) or 0.35
		if mode == "Pulse" then
			local a, b = rgb(cfg.colAccent), rgb(cfg.colAccent2)
			local k = 0.65 + 0.35 * (0.5 + 0.5 * math.sin(t * speed * 6.2832))
			local black = Color3.new(0, 0, 0)
			return a:Lerp(black, 1 - k), b:Lerp(black, 1 - k)
		elseif mode == "Fade" then
			local a, b = rgb(cfg.colAccent), rgb(cfg.colAccent2)
			local k = 0.5 + 0.5 * math.sin(t * speed * 6.2832)
			return a:Lerp(b, k), b:Lerp(a, k)
		end
		local h = (t * speed) % 1
		return Color3.fromHSV(h, sat, val), Color3.fromHSV((h + spread) % 1, sat, val * 0.82)
	end

	local ACCENT_PROPS: any = {
		Frame = { "BackgroundColor3" },
		CanvasGroup = { "BackgroundColor3" },
		TextLabel = { "BackgroundColor3", "TextColor3" },
		TextButton = { "BackgroundColor3", "TextColor3" },
		TextBox = { "BackgroundColor3", "TextColor3" },
		ImageLabel = { "BackgroundColor3", "ImageColor3" },
		ImageButton = { "BackgroundColor3", "ImageColor3" },
		ScrollingFrame = { "BackgroundColor3", "ScrollBarImageColor3" },
		UIStroke = { "Color" },
	}
	local function track(inst: Instance, prop: string, which: number)
		local m = Rainbow.map[inst]
		if not m then
			m = {}
			Rainbow.map[inst] = m
		end
		if m[prop] then
			return
		end
		m[prop] = true
		table.insert(Rainbow.entries, { inst = inst, prop = prop, which = which })
	end
	function Rainbow.reset()
		Rainbow.entries = {}
		Rainbow.map = setmetatable({}, { __mode = "k" })
		Rainbow.cur1, Rainbow.cur2 = C.accent, C.accent2
		Rainbow.rescanAt = 0
	end
	function Rainbow.scan(o1: Color3, o2: Color3)
		local gui = Menu.gui
		if not gui then
			return
		end
		for _, d in ipairs(gui:GetDescendants()) do
			local cn = d.ClassName
			local props = ACCENT_PROPS[cn]
			if props then
				for _, p in ipairs(props) do
					local w = nearWhich((d :: any)[p], o1, o2)
					if w then
						track(d, p, w)
					end
				end
			elseif cn == "UIGradient" then
				local seq = (d :: any).Color
				for _, kp in ipairs(seq.Keypoints) do
					if nearWhich(kp.Value, o1, o2) then
						track(d, "Color", 0)
						break
					end
				end
			end
		end
	end
	function Rainbow.step(dt: number)
		if not rainbowActive() or not Menu.gui then
			return
		end
		Rainbow.acc += dt
		if Rainbow.acc < 1 / 24 then
			return
		end
		Rainbow.t += Rainbow.acc
		Rainbow.acc = 0
		local n1, n2 = rainbowPair(Rainbow.t)
		local o1, o2 = Rainbow.cur1 or C.accent, Rainbow.cur2 or C.accent2
		local now = os.clock()
		if now >= Rainbow.rescanAt then
			Rainbow.rescanAt = now + 1
			Rainbow.scan(o1, o2)
		end
		local entries = Rainbow.entries
		for i = #entries, 1, -1 do
			local e = entries[i]
			local inst = e.inst
			if inst.Parent == nil then
				Rainbow.map[inst] = nil
				entries[i] = entries[#entries]
				entries[#entries] = nil
			elseif e.which == 0 then
				local kps = (inst :: any).Color.Keypoints
				local out, changed = {}, false
				for j, kp in ipairs(kps) do
					local w = nearWhich(kp.Value, o1, o2)
					if w then
						changed = true
						out[j] = ColorSequenceKeypoint.new(kp.Time, if w == 1 then n1 else n2)
					else
						out[j] = kp
					end
				end
				if changed then
					(inst :: any).Color = ColorSequence.new(out)
				end
			else
				local cur = (inst :: any)[e.prop]
				if near(cur, if e.which == 1 then o1 else o2) then
					(inst :: any)[e.prop] = if e.which == 1 then n1 else n2
				end
			end
		end
		C.accent, C.accent2 = n1, n2
		Rainbow.cur1, Rainbow.cur2 = n1, n2
		pcall(Menu.applyGlass)
	end
	Rainbow.reset()

	local TextRb: any = { entries = {}, t = 0, acc = 0, applied = false }
	KI.textRb = TextRb
	function KI.textScan()
		TextRb.entries = {}
		local root = Menu.root
		if not root then
			return
		end
		for _, d in ipairs(root:GetDescendants()) do
			local cn = d.ClassName
			if cn == "TextLabel" or cn == "TextButton" then
				local col = (d :: any).TextColor3
				if near(col, C.text) or near(col, C.dim) then
					table.insert(TextRb.entries, { inst = d, orig = col, last = col })
				end
			end
		end
	end
	function TextRb.step(dt: number)
		local on = cfg.rainbowText == true
		if not on and not TextRb.applied then
			return
		end
		if not Menu.gui then
			return
		end
		TextRb.acc += dt
		if TextRb.acc < 1 / 20 then
			return
		end
		TextRb.t += TextRb.acc
		TextRb.acc = 0
		local speed = tonumber(cfg.textSpeed) or 0.3
		local sat = math.clamp(tonumber(cfg.textSat) or 0.55, 0, 1)
		local wave = math.clamp(tonumber(cfg.textWave) or 0.5, 0, 1)
		local entries = TextRb.entries
		for i = #entries, 1, -1 do
			local e = entries[i]
			local inst = e.inst
			if inst.Parent == nil then
				entries[i] = entries[#entries]
				entries[#entries] = nil
			else
				local cur = (inst :: any).TextColor3
				if near(cur, e.last) or near(cur, e.orig) then
					local nc
					if on then
						local p = (inst :: any).AbsolutePosition
						nc = Color3.fromHSV((TextRb.t * speed + (p.X + p.Y * 0.6) * 0.0011 * wave) % 1, sat, 1)
					else
						nc = e.orig
					end
					(inst :: any).TextColor3 = nc
					e.last = nc
				end
			end
		end
		if not on then
			TextRb.applied = false
		else
			TextRb.applied = true
		end
	end

	do
		local baseApply = UI.applyTheme
		UI.applyTheme = function()
			baseApply()
			local preset = BG_PRESETS[cfg.menuBg]
			local base = UI.C_BASE
			if preset and base then
				for _, k in ipairs({ "bg", "side", "surface", "card", "pop" }) do
					if base[k] then
						C[k] = base[k]:Lerp(preset.tint, preset.amt)
					end
				end
				for _, k in ipairs({ "hairline", "edge" }) do
					if base[k] then
						C[k] = base[k]:Lerp(preset.tint, preset.amt * 0.5)
					end
				end
			end
			if rainbowActive() then
				C.accent, C.accent2 = rainbowPair(Rainbow.t)
			end
		end

		local glassParts: any = {}
		local function glassAlpha(): number
			return math.clamp(tonumber(cfg.glassAlpha) or 0.35, 0, 0.85)
		end

		function KI.glassScan()
			glassParts = {}
			local root = Menu.root
			if not root then
				return
			end
			for _, d in ipairs(root:GetDescendants()) do
				local cn = d.ClassName
				if cn == "Frame" or cn == "TextButton" then
					local gd = d :: any
					if gd.BackgroundTransparency == 0 then
						if gd.Name == "Card" then
							table.insert(glassParts, { inst = gd, base = 0.18, scale = 0.7 })
						elseif near(gd.BackgroundColor3, C.surface) or near(gd.BackgroundColor3, C.card) then
							table.insert(glassParts, { inst = gd, base = 0.22, scale = 0.55 })
						end
					end
				end
			end
		end
		local function paintGlassParts()
			local a = glassAlpha()
			for i = #glassParts, 1, -1 do
				local e = glassParts[i]
				if e.inst.Parent == nil then
					table.remove(glassParts, i)
				else
					e.inst.BackgroundTransparency = math.clamp(e.base + a * e.scale, 0, 0.95)
				end
			end
		end
		local baseGlass = Menu.applyGlass
		Menu.applyGlass = function()
			baseGlass()
			local g = Menu.glassGrad
			if not g then
				return
			end
			local tint = math.clamp(tonumber(cfg.glassTint) or 0.5, 0, 1)
			local a = glassAlpha()
			local r = math.clamp(Menu.glassSplit or 0.22, 0.01, 0.98)
			local railA = if UI.metal then 0 else math.clamp((tonumber(cfg.railGlass) or 14) / 100, 0, 0.4)
			local rail = C.side:Lerp(C.accent2, 0.16 + 0.34 * tint)
			local keys = {
				ColorSequenceKeypoint.new(0, rail),
				ColorSequenceKeypoint.new(r - 0.002, rail),
			}

			local steps = 5
			for i = 0, steps - 1 do
				local k = i / (steps - 1)
				local c = C.bg:Lerp(C.accent:Lerp(C.accent2, k), 0.12 + 0.4 * tint)
				table.insert(keys, ColorSequenceKeypoint.new(r + (1 - r) * k, c))
			end
			g.Color = ColorSequence.new(keys)
			g.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, railA),
				NumberSequenceKeypoint.new(r - 0.002, railA),
				NumberSequenceKeypoint.new(r, a),
				NumberSequenceKeypoint.new(1, a),
			})
			paintGlassParts()
		end
		local baseBuild = Menu.build
		Menu.build = function(...)
			local r = baseBuild(...)
			Rainbow.reset()
			pcall(KI.glassScan)
			pcall(KI.textScan)
			pcall(KI.loadBg)
			pcall(Menu.applyGlass)
			return r
		end
	end

	do
		local baseSet = Menu.set
		Menu.set = function(open: boolean)
			baseSet(open)
			if open then
				pcall(KI.loadBg)
			else
				saveConfig()
			end
		end
	end

	do
		local MC_FONT = Font.fromEnum(Enum.Font.Arcade)
		local function forceFont()
			for _, k in ipairs({ "body", "medium", "semibold", "bold", "black", "code" }) do
				UI.F[k] = MC_FONT
			end
			UI.HUD_FONT, UI.HUD_BOLD, UI.BRAND_FONT = MC_FONT, MC_FONT, MC_FONT
		end
		forceFont()
		KI.forceFont = forceFont
	end

	local UE: any = { last = 0 }
	KI.ue = UE
	KI.extraRoots = {}

	local function ueMeta(kind: string?, get: any, set: any): (string, any)
		KI.localSeq += 1
		local key = "k:ue" .. KI.localSeq
		local meta = {
			key = key,
			kind = kind,
			get = get,
			set = function(v: any)
				set(v)
				if UE.saveSoon then
					UE.saveSoon()
				end
			end,
		}
		KI.keyMeta[key] = meta
		return key, meta
	end
	local function ueHandle(kind: string, label: any, opts: any, tag: string?, get: any, set: any): any
		opts = opts or {}
		opts.Label = tostring(label or "")
		local h = newHandle(kind, opts)
		h.Row.Label = opts.Label
		local key, meta = ueMeta(tag, get, set)
		h._key, h._meta = key, meta
		return h
	end

	local function proxyOf(real: any, rec: any): any
		return setmetatable({}, {
			__index = function(_, k)
				local r = rec[k]
				if r ~= nil then
					return r
				end
				local v = real[k]
				if type(v) == "function" then
					return function(_, ...)
						return v(real, ...)
					end
				end
				return v
			end,
			__newindex = function(_, k, v)
				real[k] = v
			end,
		})
	end
	function UE.touch()
		UE.last = os.clock()
		if UE.timer then
			return
		end
		UE.timer = true
		task.spawn(function()
			repeat
				task.wait(0.5)
			until os.clock() - UE.last > 1.5
			UE.timer = false
			if KI.refreshTabs then
				pcall(KI.refreshTabs)
			end
			if UE.setupAutosave and not UE.autosaveOn then
				pcall(UE.setupAutosave)
			end
		end)
	end

	local wrapContainer: any

	local function attachRec(real: any, sec: any, label: string, labelItem: any): any
		local rec = {}
		function rec.AddColorPicker(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddColorPicker(idx, info)
			local o = obj
			local h = ueHandle("color", info.Title or label or tostring(idx), { Tooltip = info.Tooltip }, "color", function()
				return o.Value
			end, function(v: any)
				pcall(o.SetValueRGB, o, v)
			end)
			if labelItem then
				labelItem.skip = true
			end
			push(sec, "color", h._opts, h)
			return obj
		end
		function rec.AddKeyPicker(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddKeyPicker(idx, info)
			if not info.NoUI then
				local h = newHandle("uekey", { Label = tostring(info.Text or label or idx) })
				h.kp = obj
				if labelItem then
					labelItem.skip = true
				end
				push(sec, "uekey", h._opts, h)
			end
			return obj
		end
		return rec
	end
	local function recordButton(owner: any, sec: any, a: any, b: any): any
		local obj = owner:AddButton(a, b)
		local text, fn, dbl, tip
		if type(a) == "table" then
			text, fn, dbl, tip = a.Text, a.Func, a.DoubleClick, a.Tooltip
		else
			text, fn = a, b
		end
		local h = newHandle("button", { Label = tostring(text or ""), OnClick = fn, Confirm = dbl == true, Tooltip = tip })
		push(sec, "button", h._opts, h)
		local chain = {}
		function chain.AddButton(_, a2: any, b2: any)
			return recordButton(obj, sec, a2, b2)
		end
		return proxyOf(obj, chain)
	end

	wrapContainer = function(real: any, sec: any): any
		local rec = {}
		function rec.AddToggle(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddToggle(idx, info)
			local text = tostring(info.Text or "")
			if idx == "INVISIBLE_IGNORE_ME_THANKS" or text == "" then
				return obj
			end
			local o = obj
			local h = ueHandle("toggle", text, { Tooltip = info.Tooltip }, nil, function()
				return o.Value
			end, function(v: any)
				o:SetValue(v == true)
			end)
			push(sec, "toggle", h._opts, h)
			return proxyOf(obj, attachRec(obj, sec, text, nil))
		end
		function rec.AddSlider(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddSlider(idx, info)
			local o = obj
			local step = 10 ^ -(tonumber(info.Rounding) or 0)
			local h = ueHandle(
				"slider",
				info.Text or tostring(idx),
				{ Tooltip = info.Tooltip, Min = info.Min, Max = info.Max, Step = step, Suffix = info.Suffix },
				nil,
				function()
					return o.Value
				end,
				function(v: any)
					o:SetValue(v)
				end
			)
			push(sec, "slider", h._opts, h)
			return obj
		end
		function rec.AddDropdown(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddDropdown(idx, info)
			local o = obj
			local multi = info.Multi == true
			local h = ueHandle(if multi then "multi" else "dropdown", info.Text or tostring(idx), {
				Tooltip = info.Tooltip,
				GetOptions = function()
					return o.Values
				end,
			}, if multi then "multi" else nil, function()
				return o.Value
			end, function(v: any)
				o:SetValue(v)
			end)
			push(sec, h._kind, h._opts, h)
			return obj
		end
		function rec.AddInput(_, idx: any, info: any)
			info = info or {}
			local obj = real:AddInput(idx, info)
			local o = obj
			local h = ueHandle("textbox", info.Text or tostring(idx), { Tooltip = info.Tooltip, Placeholder = info.Placeholder }, nil, function()
				return o.Value or ""
			end, function(v: any)
				o:SetValue(tostring(v))
			end)
			push(sec, "textbox", h._opts, h)
			return obj
		end
		function rec.AddButton(_, a: any, b: any)
			return recordButton(real, sec, a, b)
		end
		function rec.AddLabel(_, text: any, wrap: any)
			local obj = real:AddLabel(text, wrap)
			local h = newHandle("label", { Label = tostring(text or "") })
			push(sec, "label", h._opts, h)
			local labelItem = sec.items[#sec.items]
			return proxyOf(obj, attachRec(obj, sec, tostring(text or ""), labelItem))
		end
		function rec.AddDivider(_)
			return real:AddDivider()
		end
		function rec.AddBlank(_, size: any)
			return real:AddBlank(size)
		end
		function rec.AddDependencyBox(_)
			local obj = real:AddDependencyBox()
			local node = newSection(sec.title, sec.side)
			node.isGroup = true
			node.pred = function()
				return true
			end
			table.insert(sec.items, { kind = "group", opts = {}, node = node })
			KI.dirty = true
			return wrapContainer(obj, node)
		end
		function rec.SetupDependencies(_, deps: any)
			real:SetupDependencies(deps)
			sec.pred = function()
				for _, d in ipairs(deps or {}) do
					local o, want = d[1], d[2]
					local ok, cur = pcall(function()
						return o.Value
					end)
					if not ok or cur ~= want then
						return false
					end
				end
				return true
			end
		end
		return proxyOf(real, rec)
	end

	local function wrapTab(realTab: any, grid: any): any
		local rec = {}
		local function groupbox(method: string, side: string)
			return function(_, name: any)
				local realBox = realTab[method](realTab, name)
				local sec = newSection(name, side)
				table.insert(grid.sections, sec)
				KI.dirty = true
				UE.touch()
				return wrapContainer(realBox, sec)
			end
		end
		local function tabbox(method: string, side: string)
			return function(_, name: any)
				local realTB = realTab[method](realTab, name)
				local rec2 = {}
				function rec2.AddTab(_, tname: any)
					local realT = realTB:AddTab(tname)
					local sec = newSection(tostring(tname), side)
					table.insert(grid.sections, sec)
					KI.dirty = true
					UE.touch()
					return wrapContainer(realT, sec)
				end
				return proxyOf(realTB, rec2)
			end
		end
		rec.AddLeftGroupbox = groupbox("AddLeftGroupbox", "left")
		rec.AddRightGroupbox = groupbox("AddRightGroupbox", "right")
		rec.AddLeftTabbox = tabbox("AddLeftTabbox", "left")
		rec.AddRightTabbox = tabbox("AddRightTabbox", "right")
		return proxyOf(realTab, rec)
	end

	local function wrapWindow(realWin: any): any
		local rec = {}
		function rec.AddTab(_, name: any)
			local realTab = realWin:AddTab(name)
			local node = newTab({ Label = tostring(name) }, UE.root)
			table.insert(UE.root.children, node)
			local grid = node:Grid({ Columns = 2 })
			UE.touch()
			return wrapTab(realTab, grid)
		end
		return proxyOf(realWin, rec)
	end

	function KC.ueHook(Library: any)
		if UE.hooked == Library then
			return
		end
		UE.hooked = Library
		if not UE.root then
			UE.root = newTab({ Label = "UE" }, nil)
			table.insert(KI.extraRoots, UE.root)
		end
		local origCreate = Library.CreateWindow
		Library.CreateWindow = function(self: any, info: any)
			info = info or {}
			info.AutoShow = false
			local win = origCreate(self, info)

			Library.Toggle = function() end
			Library.Toggled = false

			pcall(function()
				local gui = Library.ScreenGui
				gui.Enabled = false
				gui:GetPropertyChangedSignal("Enabled"):Connect(function()
					if gui.Enabled then
						gui.Enabled = false
					end
				end)
			end)
			return wrapWindow(win)
		end
		Library.Notify = function(_: any, text: any)
			notify(tostring(text), 4, "info")
		end
		log("INFO", "UE library hooked")
	end

	local toastGui: any, toastHolder: any
	local toastList: { any } = {}
	local function toastColor(kind: string?): Color3
		if kind == "ok" then
			return C.ok
		elseif kind == "warn" then
			return C.warn
		elseif kind == "error" then
			return C.danger
		end
		return C.accent
	end
	local function ensureToasts(): boolean
		if toastGui and toastGui.Parent and toastHolder then
			return true
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "KiciaToasts"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 1100
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		if not Game.parentGui(gui) then
			return false
		end
		local holder = Instance.new("Frame")
		holder.Name = "Holder"
		holder.BackgroundTransparency = 1
		holder.AnchorPoint = Vector2.new(1, 0)
		holder.Position = UDim2.new(1, -18, 0, 18)
		holder.Size = UDim2.fromOffset(300, 0)
		holder.AutomaticSize = Enum.AutomaticSize.Y
		holder.Parent = gui
		local lay = Instance.new("UIListLayout")
		lay.Padding = UDim.new(0, 8)
		lay.SortOrder = Enum.SortOrder.LayoutOrder
		lay.HorizontalAlignment = Enum.HorizontalAlignment.Right
		lay.Parent = holder
		toastGui, toastHolder = gui, holder
		return true
	end
	local toastSeq = 0
	function KI.toast(text: any, duration: any, kind: any)
		if not ensureToasts() then
			return
		end
		text = tostring(text or "")
		duration = math.clamp(tonumber(duration) or 3.5, 1.5, 10)
		local col = toastColor(kind)
		toastSeq += 1
		local card = Instance.new("Frame")
		card.Name = "Toast"
		card.BackgroundColor3 = C.pop
		card.BackgroundTransparency = 1
		card.BorderSizePixel = 0
		card.Size = UDim2.new(1, 0, 0, 0)
		card.AutomaticSize = Enum.AutomaticSize.Y
		card.LayoutOrder = toastSeq
		card.ClipsDescendants = true
		corner(card, 8)
		local st = stroke(card, col, 1)
		local pad = Instance.new("UIPadding")
		pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 9), UDim.new(0, 11)
		pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 16), UDim.new(0, 12)
		pad.Parent = card
		local bar = Instance.new("Frame")
		bar.Name = "Accent"
		bar.BackgroundColor3 = col
		bar.BackgroundTransparency = 1
		bar.BorderSizePixel = 0
		bar.Position = UDim2.fromOffset(-16, -9)
		bar.Size = UDim2.new(0, 3, 1, 20)
		bar.ZIndex = 2
		bar.Parent = card
		local title = Instance.new("TextLabel")
		title.Name = "Kind"
		title.BackgroundTransparency = 1
		title.Size = UDim2.new(1, 0, 0, 14)
		title.Text = string.lower(tostring(kind or "info"))
		title.FontFace = UI.F.body
		title.TextSize = 12
		title.TextColor3 = col
		title.TextTransparency = 1
		title.TextXAlignment = Enum.TextXAlignment.Left
		title.Parent = card
		local msg = Instance.new("TextLabel")
		msg.Name = "Text"
		msg.BackgroundTransparency = 1
		msg.Position = UDim2.fromOffset(0, 16)
		msg.Size = UDim2.new(1, 0, 0, 0)
		msg.AutomaticSize = Enum.AutomaticSize.Y
		msg.Text = text
		msg.FontFace = UI.F.body
		msg.TextSize = 13
		msg.TextColor3 = C.text
		msg.TextTransparency = 1
		msg.TextWrapped = true
		msg.TextXAlignment = Enum.TextXAlignment.Left
		msg.TextYAlignment = Enum.TextYAlignment.Top
		msg.Parent = card

		local spacer = Instance.new("Frame")
		spacer.BackgroundTransparency = 1
		spacer.Size = UDim2.new(1, 0, 0, 16)
		spacer.Parent = card
		local timer = Instance.new("Frame")
		timer.Name = "Timer"
		timer.BackgroundColor3 = col
		timer.BackgroundTransparency = 0.35
		timer.BorderSizePixel = 0
		timer.AnchorPoint = Vector2.new(0, 1)
		timer.Position = UDim2.new(0, -16, 1, 11)
		timer.Size = UDim2.new(1, 28, 0, 2)
		timer.ZIndex = 3
		timer.Parent = card
		card.Parent = toastHolder
		table.insert(toastList, card)
		while #toastList > 5 do
			local old = table.remove(toastList, 1)
			pcall(old.Destroy, old)
		end
		local info = TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		TweenService:Create(card, info, { BackgroundTransparency = 0.12 }):Play()
		TweenService:Create(st, info, { Transparency = 0.45 }):Play()
		TweenService:Create(bar, info, { BackgroundTransparency = 0 }):Play()
		TweenService:Create(title, info, { TextTransparency = 0.1 }):Play()
		TweenService:Create(msg, info, { TextTransparency = 0 }):Play()
		TweenService:Create(timer, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 2) }):Play()
		task.delay(duration, function()
			if not card.Parent then
				return
			end
			local out = TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
			TweenService:Create(card, out, { BackgroundTransparency = 1 }):Play()
			TweenService:Create(st, out, { Transparency = 1 }):Play()
			TweenService:Create(bar, out, { BackgroundTransparency = 1 }):Play()
			TweenService:Create(title, out, { TextTransparency = 1 }):Play()
			TweenService:Create(msg, out, { TextTransparency = 1 }):Play()
			TweenService:Create(timer, out, { BackgroundTransparency = 1 }):Play()
			task.delay(0.3, function()
				local i = table.find(toastList, card)
				if i then
					table.remove(toastList, i)
				end
				pcall(card.Destroy, card)
			end)
		end)
	end

	do
		local baseNotify = notify
		notify = function(text: any, duration: any, kind: any)
			local ok = pcall(KI.toast, text, duration, kind)
			if not ok then
				baseNotify(text, duration, kind)
			end
		end
	end

	function UE.saveSoon()
		if not UE.autosaveOn or UE.savePending then
			return
		end
		UE.savePending = true
		task.delay(1.2, function()
			UE.savePending = false
			local sm = genv().SaveManager
			if sm and sm.Save then
				pcall(sm.Save, sm, "autosave")
			end
		end)
	end
	function UE.setupAutosave()
		local sm = genv().SaveManager
		if not sm or not sm.Save then
			return
		end
		local folder = tostring(sm.Folder or "unnamed/rivals")
		local autoFile = folder .. "/settings/autoload.txt"
		local cfgFile = folder .. "/settings/autosave.json"
		pcall(function()
			EXEC.mkdirs(folder .. "/settings")
			if not EXEC.isfile(autoFile) then
				EXEC.writefile(autoFile, "autosave")

				if EXEC.isfile(cfgFile) and sm.Load then
					pcall(sm.Load, sm, "autosave")
				end
			end
		end)
		UE.autosaveOn = true
	end

	local BG_DIR = "kiciarebuild"
	local BG_DEFAULT_URL = "https://i.postimg.cc/Qt8dv7Nv/images.jpg"
	local BG_EMBEDDED = ""

	local function isImage(body: any): boolean
		if type(body) ~= "string" or #body < 500 then
			return false
		end
		local a, b = string.byte(body, 1, 2)
		return (a == 0xFF and b == 0xD8) or (a == 0x89 and b == 0x50)
	end

	local function decodeBase64(text: string): string?
		local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local map = {}
		for i = 1, 64 do
			map[string.byte(alphabet, i)] = i - 1
		end
		local ok, out = pcall(function()
			local buf = buffer.create(#text * 3 // 4 + 3)
			local n = 0
			for i = 1, #text, 4 do
				local a, b, c, d = string.byte(text, i, i + 3)
				local vc, vd = map[c], map[d]
				local v = map[a] * 262144 + map[b] * 4096 + (vc or 0) * 64 + (vd or 0)
				buffer.writeu8(buf, n, bit32.rshift(v, 16))
				n += 1
				if vc then
					buffer.writeu8(buf, n, bit32.band(bit32.rshift(v, 8), 255))
					n += 1
				end
				if vd then
					buffer.writeu8(buf, n, bit32.band(v, 255))
					n += 1
				end
			end
			return buffer.readstring(buf, 0, n)
		end)
		if ok and type(out) == "string" then
			return out
		end
		return nil
	end

	local function fetchBytes(url: string): string?
		local ok, body = pcall(function()
			return game:HttpGet(url, true)
		end)
		if ok and isImage(body) then
			return body
		end
		if type(EXEC.request) == "function" then
			local okR, res = pcall(EXEC.request, { Url = url, Method = "GET" })
			if okR and type(res) == "table" and res.StatusCode == 200 and isImage(res.Body) then
				return res.Body
			end
		end
		return nil
	end

	local function bgFn(name: string, alt: any): any
		local direct = if name == "writefile" then writefile
			elseif name == "readfile" then readfile
			elseif name == "isfile" then isfile
			else getcustomasset or getsynasset or get_custom_asset
		return if type(direct) == "function" then direct else alt
	end

	local function tryAsset(path: string, body: string): (string?, string?)
		local write, read, asset = bgFn("writefile", EXEC.writefile), bgFn("readfile", EXEC.readfile), bgFn("getcustomasset", EXEC.getcustomasset)
		if type(write) ~= "function" or type(read) ~= "function" then
			return nil, "this executor has no writefile / readfile"
		end
		if type(asset) ~= "function" then
			return nil, "this executor has no getcustomasset"
		end
		local okW, errW = pcall(write, path, body)
		if not okW then
			return nil, "writefile failed: " .. string.sub(tostring(errW), 1, 70)
		end
		local okR, data = pcall(read, path)
		if not okR or type(data) ~= "string" or #data ~= #body then
			return nil, "the file was not stored (" .. path .. ")"
		end
		local ok, id = pcall(asset, path)
		if ok and type(id) == "string" and id ~= "" then
			return id, nil
		end
		return nil, "getcustomasset failed: " .. string.sub(tostring(id), 1, 70)
	end

	local function tryExisting(): string?
		local exists, asset = bgFn("isfile", EXEC.isfile), bgFn("getcustomasset", EXEC.getcustomasset)
		if type(exists) ~= "function" or type(asset) ~= "function" then
			return nil
		end
		for _, path in ipairs({ "chad_background.jpg", "chad_background.png", BG_DIR .. "/chad_bg.jpg" }) do
			local okE, there = pcall(exists, path)
			if okE and there then
				local ok, id = pcall(asset, path)
				if ok and type(id) == "string" and id ~= "" then
					return id
				end
			end
		end
		return nil
	end

	local function loadBgAsset(url: string): (string?, string?)
		local setId = EXEC.setIdentity or setthreadidentity
		if type(setId) == "function" then
			pcall(setId, 8)
		end
		if url == BG_DEFAULT_URL then
			local existing = tryExisting()
			if existing then
				return existing, nil
			end
		end
		local body: string? = nil
		local usedFallback = false
		if url ~= BG_DEFAULT_URL then
			body = fetchBytes(url)
		end
		if not body then
			body = decodeBase64(BG_EMBEDDED)
			if not isImage(body) then
				body = nil
			end
			usedFallback = url ~= BG_DEFAULT_URL
		end
		if not body then
			return nil, "could not read the built-in picture"
		end
		if usedFallback then
			notify("That link is not a direct .jpg / .png, using the built-in picture", 5, "warn")
		end
		local ext = if string.byte(body, 1) == 0x89 then "png" else "jpg"
		pcall(function()
			EXEC.mkdirs(BG_DIR)
		end)
		local lastWhy = "no place to store the picture"

		for _, path in ipairs({ "chad_background." .. ext, BG_DIR .. "/chad_bg." .. ext }) do
			local id, why = tryAsset(path, body)
			if id then
				return id, nil
			end
			lastWhy = tostring(why)
		end
		return nil, lastWhy
	end

	function KI.paintBg()
		local root = Menu.root
		if not root then
			return
		end
		local img = root:FindFirstChild("ChadBackground")
		local dim = root:FindFirstChild("ChadDim")
		if cfg.bgImage ~= true or not KI.bgAsset then
			if img then
				img:Destroy()
			end
			if dim then
				dim:Destroy()
			end
			return
		end
		if not img then
			img = Instance.new("ImageLabel")
			img.Name = "ChadBackground"
			img.BackgroundTransparency = 1
			img.Size = UDim2.fromScale(1, 1)
			img.ScaleType = Enum.ScaleType.Crop
			img.ZIndex = 1
			img.Active = false
			corner(img, 12)
			img.Parent = root
			dim = Instance.new("Frame")
			dim.Name = "ChadDim"
			dim.BorderSizePixel = 0
			dim.Size = UDim2.fromScale(1, 1)
			dim.ZIndex = 1
			dim.Active = false
			corner(dim, 12)
			dim.Parent = root
		end
		img.Image = KI.bgAsset
		img.ImageTransparency = 1 - math.clamp(tonumber(cfg.bgImageAlpha) or 1, 0, 1)
		dim.BackgroundColor3 = C.bg
		dim.BackgroundTransparency = 1 - math.clamp(tonumber(cfg.bgImageDim) or 0, 0, 1)
	end

	function KI.loadBg()
		if cfg.bgImage ~= true then
			KI.paintBg()
			return
		end
		local url = tostring(cfg.bgImageUrl or "")
		if url == "" then
			return
		end
		if KI.bgUrl == url and KI.bgAsset then
			KI.paintBg()
			return
		end
		if KI.bgLoading then
			return
		end
		KI.bgLoading = true
		task.spawn(function()
			local id, why = loadBgAsset(url)
			if id then
				KI.bgUrl, KI.bgAsset = url, id
			else
				KI.bgFailUrl = url
				if KI.bgToasted ~= url then
					KI.bgToasted = url
					notify("Background image: " .. tostring(why), 5, "warn")
				end
			end
			KI.bgLoading = false
			KI.paintBg()
		end)
	end
	function KI.reloadBg()
		KI.bgUrl, KI.bgAsset, KI.bgFailUrl, KI.bgToasted = nil, nil, nil, nil
		KI.loadBg()
	end

	local ShimMenu: any = {}
	ShimMenu.__index = function(s, k)
		local m = ShimMenu[k]
		if m ~= nil then
			return m
		end
		if type(k) == "string" and string.match(k, "^%u") then
			return function()
				return DUMMY
			end
		end
		return nil
	end
	local rootTabs: { any } = {}

	function KI.syncTabs()
		KI.order, KI.tabByLabel = {}, {}
		table.clear(TAB_ORDER)
		local list, settings = {}, nil
		for _, t in ipairs(rootTabs) do
			if t.label == "Settings" then
				settings = t
			else
				table.insert(list, t)
			end
		end
		for _, t in ipairs(KI.extraRoots) do
			table.insert(list, t)
		end
		if settings then
			table.insert(list, settings)
		end
		for _, t in ipairs(list) do
			local id = t.label
			KI.tabByLabel[id] = t
			table.insert(KI.order, id)
			table.insert(TAB_ORDER, id)
			Menu.TAB_LABEL[id] = id
			Menu.TAB_SECTION[id] = TOP_SECTION[id] or "Other"
			UI.ICONS[id] = TOP_ICON[id] or "tune"
		end
	end
	function KI.refreshTabs()
		if not KI.finalized then
			return
		end
		KI.syncTabs()
		KI.rebuildSoon()
	end
	function ShimMenu.new(opts: any)
		opts = opts or {}
		local self = setmetatable({
			_opts = opts,
			Fonts = DUMMY,
			Keybind = Enum.KeyCode.RightShift,
		}, ShimMenu)
		KI.adapter = opts.Config
		KI.persistence = opts.Persistence
		KI.state = opts.State
		KI.stateData = opts.StateData
		KI.colorAnimation = opts.ColorAnimation
		KI.onUnload = opts.OnUnload
		KI.title = opts.Title
		rootTabs = {}
		KI.rootTabs = rootTabs
		table.clear(KI.keybinds)
		local sd = opts.StateData
		local k = sd and parseKey(sd.Keybind)
		if k then
			self.Keybind = k
		end
		cfg.menuKey = self.Keybind.Name

		pcall(function()
			local marker = "kiciarebuild/autosave_default.txt"
			if sd and KI.persistence and not EXEC.isfile(marker) then
				if sd.AutoSave ~= true and sd.AutoLoad ~= true and not sd.AutoSaveConfigName and not sd.AutoLoadConfigName then
					pcall(KI.persistence.CreateDefault, KI.persistence, "autosave")
					sd.AutoSave, sd.AutoLoad = true, true
					sd.AutoSaveConfigName, sd.AutoLoadConfigName = "autosave", "autosave"
					self:SaveState()
				end
				EXEC.mkdirs("kiciarebuild")
				EXEC.writefile(marker, "1")
			end
		end)
		task.defer(function()
			pcall(KI.loadBg)
		end)
		pcall(KI.forceFont)
		pcall(UI.applyTheme)
		cfg.previewPane = false
		return self
	end
	function ShimMenu:AddTab(o: any)
		local t = newTab(o, nil)
		table.insert(rootTabs, t)
		KI.dirty = true
		return t
	end
	function ShimMenu:GetConfig()
		return KI.adapter
	end
	function ShimMenu:GetPersistence()
		return KI.persistence
	end
	function ShimMenu:GetStateData()
		return KI.stateData
	end
	function ShimMenu:GetState()
		return KI.state
	end
	function ShimMenu:GetColorAnimation()
		return KI.colorAnimation
	end
	function ShimMenu:SaveState()
		local st = KI.state
		if st and st.Save and KI.stateData then
			pcall(st.Save, st, KI.stateData)
		end
	end
	function ShimMenu:Notify(text: any)
		if type(text) == "table" then
			local parts = {}
			for _, p in ipairs(text) do
				table.insert(parts, tostring(type(p) == "table" and p.Text or p))
			end
			text = table.concat(parts, "")
		end
		notify(tostring(text), 4, "info")
	end
	function ShimMenu:AttachTooltip() end
	function ShimMenu:InvalidateSearch() end
	function ShimMenu:Tween() end
	function ShimMenu:SetWatermarkUsername() end
	function ShimMenu:CaptureKey(cb: any)
		local conn
		KI.capturing = true
		conn = UIS.InputBegan:Connect(function(input: InputObject)
			if input.UserInputType == Enum.UserInputType.Keyboard then
				conn:Disconnect()
				KI.capturing = false
				cb(if input.KeyCode == Enum.KeyCode.Escape then nil else input.KeyCode)
			end
		end)
		return function()
			if conn then
				conn:Disconnect()
			end
			KI.capturing = false
		end
	end

	function ShimMenu:AddSettingsTab()
		local self_ = self
		local tab = newTab({ Label = "Settings" }, nil)
		table.insert(rootTabs, tab)
		local persistence, stateData = KI.persistence, KI.stateData
		local menuTab = tab:AddTab({ Label = "Menu" })
		local menuGrid = menuTab:Grid({ Columns = 2 })
		local sMenu = menuGrid:AddSection({ Title = "Menu", Side = "left" })
		local kb = sMenu:AddKeybind({ Label = "Menu Keybind", Modes = { "Toggle" }, Default = { Key = self.Keybind, Mode = "Toggle" } })
		kb:SetFeatureEnabled(false)
		kb:OnChanged(function(v: any)
			local key = v.Key
			if typeof(key) ~= "EnumItem" then
				return
			end
			self_.Keybind = key
			cfg.menuKey = key.Name
			if stateData then
				stateData.Keybind = tostring(key.EnumType) .. "." .. key.Name
				self_:SaveState()
			end
		end)

		local sWin = menuGrid:AddSection({ Title = "Window", Side = "right" })
		table.insert(sWin.items, {
			kind = "raw",
			build = function(g: any)
				g:cycle("Menu size", "menuScale", { 0.9, 1, 1.1, 1.25 }, {
					advanced = false,
					fmt = function(v: any): string
						return ("%d%%"):format(math.floor(v * 100 + 0.5))
					end,
					onChange = function()
						task.defer(Menu.rebuild)
					end,
				})
				g:toggle("Blur behind the menu", "menuBlur", {
					advanced = false,
					onChange = function()
						pcall(Menu.blur, S.menuOpen == true)
					end,
				})
				g:slider("Blur strength", "menuBlurSize", 4, 30, 1, {
					advanced = false,
					onChange = function()
						pcall(Menu.blur, S.menuOpen == true)
					end,
				})
			end,
		})

		local themeTab = tab:AddTab({ Label = "Theme" })
		local themeGrid = themeTab:Grid({ Columns = 2 })
		local sTheme = themeGrid:AddSection({ Title = "Theme", Side = "left" })
		local sRain = themeGrid:AddSection({ Title = "Rainbow", Side = "right" })
		local sColors = themeGrid:AddSection({ Title = "Custom colors", Side = "left" })
		local sSurface = themeGrid:AddSection({ Title = "Surface", Side = "right" })
		local sImage = themeGrid:AddSection({ Title = "Background image", Side = "left" })
		table.insert(sTheme.items, {
			kind = "raw",
			build = function(g: any)
				g:cycle("Theme", "theme", THEME_ORDER, {
					advanced = false,
					desc = "Rainbow animates the accent. Custom uses the two colors below.",
					onChange = function()
						task.defer(Menu.applyTheme)
					end,
				})
				g:note("Pick Rainbow for the animated menu, then tune it on the right.", { advanced = false })
			end,
		})
