		local profTab = tab:AddTab({ Label = "Profiles" })
		local profGrid = profTab:Grid({ Columns = 2 })
		local sProf = profGrid:AddSection({ Title = "Whole-Menu Profiles", Side = "left" })
		local sTransfer = profGrid:AddSection({ Title = "Transfer", Side = "right" })
		local sAuto = profGrid:AddSection({ Title = "Automation", Side = "right" })
		local function configs(): any
			if persistence ~= nil then
				local ok, list = pcall(persistence.AllConfigs, persistence)
				if ok and type(list) == "table" then
					return list
				end
			end
			return {}
		end
		local function failed(res: any, what: string): boolean
			if type(res) == "table" and res.Ok == false then
				local detail = res.Error and res.Error.Detail or "unknown error"
				notify(what .. " failed: " .. tostring(detail), 5, "error")
				return true
			end
			return false
		end
		local nameBox = sProf:AddTextBox({ Label = "Config Name" })
		local list = sProf:AddList({ Label = "Configs", Options = configs(), Height = 160, Search = true })
		local function refreshList()
			list:SetOptions(configs())
		end
		sProf:AddButton({
			Label = "Create Config",
			OnClick = function()
				local name = string.gsub(tostring(nameBox.Value or ""), "%s+", "")
				if name == "" or not persistence then
					return
				end
				if failed(persistence:CreateDefault(name), "Creating config") then
					return
				end
				refreshList()
				list:Set(name)
			end,
		})
		sProf:AddButton({ Label = "Refresh List", OnClick = refreshList })
		sProf:AddButton({
			Label = "Load Selected Config",
			Confirm = true,
			OnClick = function()
				local v = list.Value
				if type(v) == "string" and persistence then
					failed(persistence:LoadFromFile(v), "Loading config")
				end
			end,
		})
		sProf:AddButton({
			Label = "Save to Selected Config",
			Confirm = true,
			OnClick = function()
				local v = list.Value
				if type(v) == "string" and v ~= "" and persistence then
					failed(persistence:SaveToFile(v), "Saving config")
				end
			end,
		})
		local autoSaveName = sAuto:AddDropdown({ Label = "Profile to Auto Save", Options = configs(), GetOptions = configs })
		local autoLoadName = sAuto:AddDropdown({ Label = "Profile to Auto Load", Options = configs(), GetOptions = configs })
		local autoSave = sAuto:AddToggle({ Label = "Auto Save" })
		local autoLoad = sAuto:AddToggle({ Label = "Auto Load" })
		sProf:AddButton({
			Label = "Delete Selected Config",
			Confirm = true,
			OnClick = function()
				local v = list.Value
				if type(v) ~= "string" or not persistence then
					return
				end
				if failed(persistence:DeleteFile(v), "Deleting config") then
					return
				end
				if stateData then
					if stateData.AutoSaveConfigName == v then
						stateData.AutoSaveConfigName = nil
						autoSaveName:Set(nil, true)
					end
					if stateData.AutoLoadConfigName == v then
						stateData.AutoLoadConfigName = nil
						autoLoadName:Set(nil, true)
					end
					self_:SaveState()
				end
				refreshList()
			end,
		})
		local importBox = sTransfer:AddTextBox({ Label = "Import (paste config)" })
		sTransfer:AddButton({
			Label = "Export to Clipboard",
			OnClick = function()
				if not persistence then
					return
				end
				local res = persistence:ExportToJson()
				if type(res) == "table" and res.Ok then
					pcall(function()
						EXEC.setclipboard(res.Value)
					end)
					notify("Copied your current config to the clipboard", 3, "ok")
				else
					failed(res, "Exporting config")
				end
			end,
		})
		sTransfer:AddButton({
			Label = "Import Config",
			Confirm = true,
			OnClick = function()
				local v = tostring(importBox.Value or "")
				if v ~= "" and persistence then
					failed(persistence:LoadFromJson(v), "Importing config")
				end
			end,
		})

		if stateData then
			autoSave:Set(stateData.AutoSave, true)
			autoLoad:Set(stateData.AutoLoad, true)
			autoSaveName:Set(stateData.AutoSaveConfigName, true)
			autoLoadName:Set(stateData.AutoLoadConfigName, true)
			local pick = stateData.AutoSaveConfigName or stateData.AutoLoadConfigName
			if pick ~= nil then
				list:Set(pick, true)
			end
		end
		local function saveAutomation()
			if stateData == nil then
				return
			end
			stateData.AutoSave = autoSave.Value == true
			stateData.AutoLoad = autoLoad.Value == true
			local a, b = autoSaveName.Value, autoLoadName.Value
			stateData.AutoSaveConfigName = if type(a) == "string" and a ~= "" then a else nil
			stateData.AutoLoadConfigName = if type(b) == "string" and b ~= "" then b else nil
			self_:SaveState()
		end
		autoSave:OnChanged(saveAutomation)
		autoLoad:OnChanged(saveAutomation)
		autoSaveName:OnChanged(saveAutomation)
		autoLoadName:OnChanged(saveAutomation)
		if persistence then
			local pending = false
			local okC, sig = pcall(function()
				return persistence.Changed
			end)
			if okC and sig and sig.Connect then
				sig:Connect(function()
					if pending then
						return
					end
					pending = true
					task.defer(function()
						pending = false
						if stateData == nil or not stateData.AutoSave then
							return
						end
						local n = stateData.AutoSaveConfigName
						if n ~= nil then
							failed(persistence:SaveToFile(n), "Auto-saving config")
						end
					end)
				end)
			end
		end
		return tab
	end

	do
		local origReplay = replayItems
		replayItems = function(g: any, items: any, ctx: any)
			local plain = {}
			local function flush()
				if #plain > 0 then
					origReplay(g, plain, ctx)
					plain = {}
				end
			end
			for _, it in ipairs(items) do
				if it.kind == "raw" then
					flush()
					local ok, err = pcall(it.build, g)
					if not ok then
						log("WARN", "kicia shim: raw row failed:", tostring(err))
					end
				else
					table.insert(plain, it)
				end
			end
			flush()
		end
	end

	function ShimMenu:SetVisible(visible: any, instant: any)
		if not KI.finalized then
			KI.finalized = true
			KI.syncTabs()
			local ok, err = xpcall(Menu.build, debug.traceback)
			if not ok then
				Menu.panic(err)
				return
			end
		end
		if visible == true then
			pcall(Menu.set, true)
		end
	end
	function ShimMenu:Destroy()
		pcall(Menu.destroy)
		for _, c in ipairs(KI.keyConn or {}) do
			pcall(c.Disconnect, c)
		end
		KI.keyConn = nil
		if KI.menuKeyConn then
			pcall(KI.menuKeyConn.Disconnect, KI.menuKeyConn)
			KI.menuKeyConn = nil
		end
		if KI.tickConn then
			pcall(KI.tickConn.Disconnect, KI.tickConn)
			KI.tickConn = nil
		end
		pcall(function()
			local CAS = game:GetService("ContextActionService")
			CAS:UnbindAction("KiciaCocaineMenu")
		end)
		S.alive = false
	end

	KI.menuKeyConn = UIS.InputBegan:Connect(function(input: InputObject)

		if S.menuOpen and input.UserInputType == Enum.UserInputType.MouseButton1 and Menu.root then
			local m = UIS:GetMouseLocation()
			local inset = GuiService:GetGuiInset()
			local function inside(f: GuiObject?): boolean
				if not f or not f.Visible then
					return false
				end
				local p, sz = f.AbsolutePosition, f.AbsoluteSize
				local mx, my = m.X, m.Y - inset.Y
				return mx >= p.X and mx <= p.X + sz.X and my >= p.Y and my <= p.Y + sz.Y
			end
			if not inside(Menu.root) and not (UI.popup and inside(UI.popup.frame)) then
				Menu.set(false)
			end
			return
		end
		if KI.capturing or UIS:GetFocusedTextBox() ~= nil then
			return
		end
		if input.UserInputType == Enum.UserInputType.Keyboard and Menu.pressed(input.KeyCode) then
			Menu.toggle()
		end
	end)

	pcall(function()
		local CAS = game:GetService("ContextActionService")
		pcall(CAS.UnbindAction, CAS, "KiciaCocaineMenu")
		CAS:BindActionAtPriority("KiciaCocaineMenu", function(_, state, input)
			if state ~= Enum.UserInputState.Begin or not input or KI.capturing then
				return Enum.ContextActionResult.Pass
			end
			if not Menu.pressed(input.KeyCode) then
				return Enum.ContextActionResult.Pass
			end
			Menu.toggle()
			return Enum.ContextActionResult.Sink
		end, false, 4000, Enum.KeyCode.RightShift, Enum.KeyCode.O)
	end)
	KI.tickConn = RunService.RenderStepped:Connect(function(dt: number)
		if S.menuOpen then
			pcall(Menu.tick, {})
			pcall(Rainbow.step, dt)
			pcall(TextRb.step, dt)
		end
	end)

	KC.Menu = ShimMenu
	KC.UI = UI
	KC.MenuKit = Menu
	KC.S = S
	KC.DUMMY = DUMMY
end
__uiScope()
