            end
            local function gradient(label, path)
                local t = s:AddToggle({ Label = label, Config = Q(path, "Enabled") })
                s:AddColor({ Row = t.Row, Gradient = "editable", Alpha = true, Config = Q(path, "Color"), Transparency = Q(path, "Transparency") })
