            end
            color("Name", "Name", true)
            s:AddGroup({ Source = color("Box", "Box") }):AddDropdown({ Label = "Style", Options = { "Full", "Corner" }, Config = Q("Box", "Style") })
            gradient("Filled Box", "FilledBox")
