local function aimbot_make_airborne_predicate(airborneStates, airMaterial)
    local function aimbot_is_airborne(humanoid)
    local humanoidState = humanoid:GetState()
    if airborneStates[humanoidState] then
        return true
    end
    return humanoid.FloorMaterial == airMaterial
    end
    return aimbot_is_airborne
end

local function aimbot_make_heartbeat_callback(
    activationState,
    inactiveCallback,
    targetState,
    cameraController,
    axisMatchEnabled,
    utilityRoot,
    targetInterpolationEnabled,
    cachedFighter,
    cachedAimPoint,
    interpolateAxis,
    advanceSmoothing,
    airbornePredicate,
    airborneSmoothingState,
    groundedSmoothingState,
    aimPointSmoothingState,
    vector3Constructor,
    lookAtConstructor,
    cameraSmoothingState,
    orientationConstructor,
    cameraDelta,
    playerState
)
    local function aimbot_heartbeat_update(deltaTime)
    if not activationState:GetState() then
        return inactiveCallback()
    end

    local targetPart = targetState.part
    if not targetPart then
        return inactiveCallback()
    end
    local targetCharacter = targetState.character
    if not targetCharacter then
        return inactiveCallback()
    end
    local targetHumanoid = targetCharacter.Humanoid
    if not targetHumanoid then
        return inactiveCallback()
    end

    local cameraFrame = cameraController:GetCameraCFrame()
    local cameraPosition = cameraFrame.Position
    local targetPosition = targetPart.Position
    if axisMatchEnabled then
        targetPosition = utilityRoot.utility:match_axis(targetPart, targetPosition, cameraFrame)
    end

    local aimPoint = targetPosition
    if targetInterpolationEnabled then
        local projectedPoint = cameraPosition + cameraFrame.LookVector * (cameraPosition - targetPosition).Magnitude
        if cachedFighter ~= targetState.fighter then
            cachedAimPoint = projectedPoint
            cachedFighter = targetState.fighter
        end
        if (projectedPoint - targetPosition).Magnitude < (cachedAimPoint - targetPosition).Magnitude then
            cachedAimPoint = projectedPoint
        end

        local verticalSmoothingState
        if airbornePredicate(targetHumanoid) then
            verticalSmoothingState = airborneSmoothingState
        else
            verticalSmoothingState = groundedSmoothingState
        end
        local smoothedY = interpolateAxis(
            cachedAimPoint.Y,
            targetPosition.Y,
            advanceSmoothing(verticalSmoothingState, deltaTime)
        )
        local interpolatedPoint = cachedAimPoint:Lerp(
            targetPosition,
            advanceSmoothing(aimPointSmoothingState, deltaTime)
        )
        aimPoint = vector3Constructor(interpolatedPoint.X, smoothedY, interpolatedPoint.Z)
        cachedAimPoint = aimPoint
    end

    local aimedCameraFrame = cameraFrame:Lerp(
        lookAtConstructor(cameraPosition, aimPoint),
        advanceSmoothing(cameraSmoothingState, deltaTime)
    )
    if aimedCameraFrame == aimedCameraFrame then
        cameraController:SetRotation(orientationConstructor(aimedCameraFrame:ToOrientation()))
        local swayDelta = cameraDelta(cameraFrame, aimedCameraFrame)
        local equippedItem = playerState.EquippedItem
        if equippedItem then
            local viewModel = equippedItem.ViewModel
            if viewModel then
                viewModel._sway_spring.Value = viewModel._sway_spring.Value + swayDelta * 35
                cameraController._sway_spring.Value = cameraController._sway_spring.Value + swayDelta * 0.25
            end
        end
    end
    end
    return aimbot_heartbeat_update
end

local function targeting_make_fov_visibility_callback(toggles, featurePrefix, utilityState)
    local function targeting_update_fov_visibility(requestedVisible)
    local visible = requestedVisible and toggles[featurePrefix .. "_showfov"].Value
    utilityState.drawings[featurePrefix].Visible = visible
    utilityState.drawings[featurePrefix .. "_outline"].Visible =
        toggles[featurePrefix .. "_fov_outline"].Value and visible
    end
    return targeting_update_fov_visibility
end

local targetingFovDrawingNames = {
    "aimbot",
    "aimbot_outline",
    "silent",
    "silent_outline",
}

local function targeting_center_fov_drawings(utilityState, screenCenter)
    local drawings = utilityState and utilityState.drawings
    if not drawings or typeof(screenCenter) ~= "Vector2" then
        return
    end

    for _, drawingName in targetingFovDrawingNames do
        local drawing = drawings[drawingName]
        if drawing and drawing.Position ~= screenCenter then
            drawing.Position = screenCenter
        end
    end
end

local function silent_make_get_camera_data_hook(
    selectFunction,
    originalGetCameraData,
    silentTarget,
    silentEnabledOption,
    randomInteger,
    hitChanceOption,
    silentActivationState,
    packResults,
    makeCameraData,
    manipulationState,
    playerState,
    cframeConstructor,
    projectileFlags,
    orientationConstructor,
    unpackResults,
    randomClass
)
    local function silent_get_camera_data_hook(receiver, ...)
    if selectFunction("#", ...) ~= 0 then
        return originalGetCameraData(receiver, ...)
    end

    local targetPart = silentTarget.part
    if not targetPart or not silentEnabledOption.Value then
        return originalGetCameraData(receiver, ...)
    end

    local chanceValue = hitChanceOption.Value
    if chanceValue < randomInteger(0, 99) then
        return originalGetCameraData(receiver, ...)
    end
    if not silentActivationState:GetState() then
        return originalGetCameraData(receiver, ...)
    end

    local packedCameraResults = packResults(originalGetCameraData(receiver, ...))
    local cameraData = makeCameraData("CameraData", packedCameraResults[1])
    local cameraFrame = cameraData:GetCameraCFrame()
    local muzzleFrame = cameraData:GetMuzzleCFrame()
    local manipulation = manipulationState.data
    local equippedItem = playerState.EquippedItem
    cameraData:SetHitOffset(cframeConstructor(randomClass.new():NextUnitVector() * 0.1))

    if not manipulation then
        local targetPosition = targetPart.Position
        cameraData:SetCameraCFrame(cframeConstructor(cameraFrame.Position, targetPosition))
        cameraData:SetMuzzleCFrame(cframeConstructor(muzzleFrame.Position, targetPosition))
    elseif manipulation.projectile then
        projectileFlags[chanceValue] = true
    else
        local adjustedCameraFrame = cameraFrame
        local adjustedMuzzleFrame = muzzleFrame
        if manipulation.c1 then
            adjustedCameraFrame = cframeConstructor(manipulation.c1) *
                orientationConstructor(cameraFrame:ToOrientation())
        end
        if manipulation.c2 then
            adjustedMuzzleFrame = cframeConstructor(manipulation.c2) *
                orientationConstructor(muzzleFrame:ToOrientation())
        end
        if manipulation.offset then
            adjustedMuzzleFrame = adjustedMuzzleFrame + manipulation.offset
            adjustedCameraFrame = adjustedCameraFrame + manipulation.offset
        end
        cameraData:SetCameraCFrame(adjustedCameraFrame)
        cameraData:SetMuzzleCFrame(adjustedMuzzleFrame)
        if manipulation.h_offset then
            cameraData:SetHitOffset(cframeConstructor(manipulation.h_offset))
        end
    end

    cameraData:SetHitPart(targetPart)
    return unpackResults(packedCameraResults, 1, packedCameraResults.n)
    end
    return silent_get_camera_data_hook
end

local function feature_make_option_refresh_callback(_initialValue, refreshCallback)
    local function feature_update_option_and_refresh(_newValue)
        refreshCallback()
    end
    return feature_update_option_and_refresh
end

-- generation-scoped runtime connection teardown
local runtimeEnvironment = getgenv()
local previousRuntimeTeardown = rawget(runtimeEnvironment, '__UEDEOBF_TEARDOWN')
local replacingExistingRuntime = type(previousRuntimeTeardown) == 'function'
if type(previousRuntimeTeardown) == 'function' then
    pcall(previousRuntimeTeardown)
else
    local previousLibrary = rawget(runtimeEnvironment, 'Library')
    if type(previousLibrary) == 'table' and type(previousLibrary.Unload) == 'function' then
        pcall(previousLibrary.Unload, previousLibrary)
    end
end
-- The recovered loader uses this one-shot flag to skip duplicate startup.
-- A generation-scoped reload has already torn the previous instance down, so
-- leaving the flag set would also skip every UI/feature initializer below.
runtimeEnvironment.UE_LOADED = nil
local runtimeLocalPlayer = game:GetService('Players').LocalPlayer
-- This game detaches LocalPlayer.PlayerScripts during a session, so an
-- unbounded WaitForChild here would stall the whole startup forever.  The
-- original direct index never yielded; resolve immediately when present and
-- fall back to a bounded wait only while the client is still replicating.
local runtimePlayerScripts = runtimeLocalPlayer:FindFirstChild('PlayerScripts') or runtimeLocalPlayer:WaitForChild('PlayerScripts', 5)

local function restoreRuntimeHookIfPresent(targetFunction)
    if type(targetFunction) ~= 'function'
        or type(isfunctionhooked) ~= 'function'
        or type(restorefunction) ~= 'function'
    then
        return
    end

    local checked, hooked = pcall(isfunctionhooked, targetFunction)
    if checked and hooked then
        pcall(restorefunction, targetFunction)
    end
end

-- Legacy builds did not track their hook targets. Remove the three cosmetic
-- hooks immediately on reload so they cannot run while this large chunk is
-- still initializing; guarded replacements are installed later below.
if replacingExistingRuntime and runtimePlayerScripts then
    pcall(function()
        local clientItem = require(
            runtimePlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem
        )
        restoreRuntimeHookIfPresent(clientItem._CreateViewModel)
    end)
    pcall(function()
        local itemLibrary = require(game:GetService('ReplicatedStorage').Modules.ItemLibrary)
        restoreRuntimeHookIfPresent(itemLibrary.GetViewModelImage)
    end)
    pcall(function()
        local clientEntity = require(
            runtimePlayerScripts.Modules.ClientReplicatedClasses.ClientEntity
        )
        restoreRuntimeHookIfPresent(clientEntity._PlayFinisher)
    end)
end

local runtimeHookTargets = {}
runtimeEnvironment.__UEDEOBF_HOOK_TARGETS = runtimeHookTargets

local function prepareRuntimeHookTarget(targetFunction)
    if type(targetFunction) ~= 'function' or runtimeHookTargets[targetFunction] then
        return targetFunction
    end

    -- Builds created before hook tracking left their replacements installed.
    -- On a reload, restore that legacy chain once before the first new hook.
    if replacingExistingRuntime
        and type(isfunctionhooked) == 'function'
        and type(restorefunction) == 'function'
    then
        local checked, hooked = pcall(isfunctionhooked, targetFunction)
        if checked and hooked then
            pcall(restorefunction, targetFunction)
        end
    end

    runtimeHookTargets[targetFunction] = true
    return targetFunction
end

-- Cosmetic selections can outlive the game's catalog. Never pass a stale
-- skin name into ClientViewModel: its constructor immediately clones the
-- matching model and assumes both metadata and the model exist.
local cosmeticValidationItemLibrary
local cosmeticValidationLibrary
local cosmeticValidationUtility
local function loadCosmeticValidationModules()
    if cosmeticValidationItemLibrary and cosmeticValidationLibrary and cosmeticValidationUtility then
        return true
    end

    local modules = game:GetService('ReplicatedStorage'):FindFirstChild('Modules')
    local itemLibraryModule = modules and modules:FindFirstChild('ItemLibrary')
    local cosmeticLibraryModule = modules and modules:FindFirstChild('CosmeticLibrary')
    local utilityModule = modules and modules:FindFirstChild('Utility')
    if not (itemLibraryModule and cosmeticLibraryModule and utilityModule) then
        return false
    end

    local loaded, itemLibrary, cosmeticLibrary, utility = pcall(function()
        return require(itemLibraryModule), require(cosmeticLibraryModule), require(utilityModule)
    end)
    if not loaded then
        return false
    end

    cosmeticValidationItemLibrary = itemLibrary
    cosmeticValidationLibrary = cosmeticLibrary
    cosmeticValidationUtility = utility
    return true
end

local function resolveEquippableSkin(baseWeaponName, candidateSkinName, cosmeticsCache)
    if type(baseWeaponName) ~= 'string' or type(candidateSkinName) ~= 'string' or candidateSkinName == '' then
        return nil
    end

    -- When the generated cache is available, require the skin to belong to
    -- this exact base weapon. This also rejects names from old saved configs.
    local skinsByWeapon = type(cosmeticsCache) == 'table' and cosmeticsCache.skin
    local compatibleSkins = type(skinsByWeapon) == 'table' and skinsByWeapon[baseWeaponName]
    if type(compatibleSkins) == 'table' and not table.find(compatibleSkins, candidateSkinName) then
        return nil
    end

    if not loadCosmeticValidationModules() then
        return nil
