                                                                            local function makeDuelSetup(resetCache, state, localPlayer)
                                                                                return function(subject)
                                                                                    if not subject then
                                                                                        resetCache()
                                                                                        return
                                                                                    end
                                                                                    state.duel_cache.list = subject._duelers_by_player
                                                                                    state.duel_cache.current = subject
