                                                                                        state.events.esp_dueler_added:Fire(function()
                                                                                            return dueler.Player, dueler
                                                                                        end)
                                                                                    end))
                                                                                    trackRuntimeConnection(subject.DuelerRemoved:Connect(function(dueler)
                                                                                        state.events.esp_dueler_removed:Fire(dueler.Player)
                                                                                    end))
                                                                                    for _, dueler in subject._duelers_by_player do
                                                                                        if dueler.Player ~= localPlayer then
