                                                                            local function makeHitEffectsHandler(
                                                                                players,
                                                                                readLocalCharacterRecord,
                                                                                targetHitNotify,
                                                                                state,
                                                                                targetHitNotifyDuration,
                                                                                hitEffectsEnabled,
                                                                                hitEffectsSelected,
                                                                                hitSoundsEnabled,
                                                                                hitSoundsSelected,
                                                                                hitSoundsVolume,
                                                                                hitEffectRegistry
                                                                            )
                                                                                return function(hitPart, damage, isHead)
                                                                                    local targetCharacter = hitPart.Parent
                                                                                    local targetPlayer = players:GetPlayerFromCharacter(targetCharacter)
                                                                                    local targetName
                                                                                    if targetPlayer then
                                                                                        targetName = targetPlayer.Name
                                                                                    else
                                                                                        targetName = targetCharacter.Name
                                                                                    end
                                                                                    local localCharacterRecord = readLocalCharacterRecord()
                                                                                    local equippedItem = localCharacterRecord.EquippedItem
                                                                                    local weaponName
                                                                                    if equippedItem then
                                                                                        weaponName = equippedItem.Name
                                                                                    else
                                                                                        weaponName = "?"
                                                                                    end
                                                                                    if targetHitNotify.Value then
                                                                                        local templates = state.notify.hit
                                                                                        local message
                                                                                        if #templates > 0 then
                                                                                            message = templates[math.random(1, #templates)]
                                                                                        else
                                                                                            message = "Hit {NAME} for {DMG} in the {PART}"
                                                                                        end
                                                                                        local partName
                                                                                        if isHead then
                                                                                            partName = "Head"
                                                                                        else
                                                                                            partName = "Body"
                                                                                        end
                                                                                        message = string.gsub(message, "{NAME}", targetName)
                                                                                        message = string.gsub(message, "{DMG}", damage)
                                                                                        message = string.gsub(message, "{PART}", partName)
                                                                                        message = string.gsub(message, "{WEAPON}", weaponName)
                                                                                        state.library:Notify(message, targetHitNotifyDuration.Value)
                                                                                    end
                                                                                    if hitSoundsEnabled.Value then
                                                                                        local sound = Instance.new("Sound", game:GetService("SoundService"))
                                                                                        sound.SoundId = state.sounds.hit[hitSoundsSelected.Value]
                                                                                        sound.Playing = true
                                                                                        sound.Volume = hitSoundsVolume.Value
                                                                                        task.delay(sound.TimeLength + 5, function()
                                                                                            sound:Destroy()
                                                                                        end)
                                                                                    end
                                                                                    if hitEffectsEnabled.Value then
                                                                                        for effectName, selected in hitEffectsSelected.Value do
                                                                                            if selected then
                                                                                                task.spawn(
                                                                                                    pcall,
                                                                                                    hitEffectRegistry[effectName],
                                                                                                    hitPart,
                                                                                                    damage,
                                                                                                    targetName,
                                                                                                    weaponName
                                                                                                )
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
