    __ue_sharedEnv.Toggles   = __ue_previousToggles
    __ue_sharedEnv.UE_LOADED = __ue_previousLoaded

    return __ue_control
end

__ue_control.status  = 'entry_returned'
__ue_control.elapsed = os.clock() - __ue_control.started

local __ue_appLib = rawget(__ue_sharedEnv, 'Library')
if type(__ue_appLib) == 'table' and __ue_appLib ~= __ue_previousLibrary and typeof(__ue_appLib.ScreenGui) == 'Instance' then
    __ue_appLib.ScreenGui.Destroying:Connect(function()
        __ue_control.status  = 'unloaded'
        __ue_control.stopped = true
        __ue_sharedEnv.UE_LOADED = __ue_previousLoaded
        if rawget(__ue_sharedEnv, 'Library') == __ue_appLib then
            __ue_sharedEnv.Library = __ue_previousLibrary
            __ue_sharedEnv.Options = __ue_previousOptions
            __ue_sharedEnv.Toggles = __ue_previousToggles
        end
    end)
end

return __ue_control


end
task.spawn(function()
	local okUE, errUE = xpcall(__UE_MAIN, debug.traceback)
	if not okUE then
		warn("[UE] " .. tostring(errUE))
	end
end)
